window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s7-119","number":119,"surah":7,"verses":[22],"verseLabel":"الأعراف: 22","question":"لماذا جاء العتاب في سؤالين: ﴿ألم أنهكما... وأقل لكما﴾؟","answer":"الأول تقرير للنهي الذي خالفاه، والثاني تقرير للتحذير من عداوة الشيطان؛ فجمع موضع المعصية وسبب الوقوع فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص61–74.","url":""}]},{"id":"s7-120","number":120,"surah":7,"verses":[23],"verseLabel":"الأعراف: 23","question":"ما سرّ افتتاح اعترافهما بقولهما: ﴿ربنا﴾؟","answer":"بدأا بـ﴿ربنا﴾ إظهارًا للعبودية والافتقار واستعطافًا بصفة التربية والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص74–84.","url":""}]},{"id":"s7-121","number":121,"surah":7,"verses":[23],"verseLabel":"الأعراف: 23","question":"ما دلالة قولهما: ﴿ظلمنا أنفسنا﴾ بدلًا من: عصيناك؟","answer":"نسبا الظلم إلى نفسيهما أدبًا واعترافًا بتحمل تبعة المعصية، وبيّنا أن ضررها عائد عليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص74–84.","url":""}]},{"id":"s7-122","number":122,"surah":7,"verses":[23],"verseLabel":"الأعراف: 23","question":"ما سرّ تقديم المغفرة على الرحمة: ﴿وإن لم تغفر لنا وترحمنا﴾؟","answer":"قُدمت المغفرة لأنها إزالة أثر الذنب، ثم تأتي الرحمة بتحصيل الخير والفضل؛ فالتخلية قبل التحلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص74–84.","url":""}]},{"id":"s7-123","number":123,"surah":7,"verses":[23],"verseLabel":"الأعراف: 23","question":"لماذا أكدا: ﴿لنكونن من الخاسرين﴾؟","answer":"نون التوكيد مع اللام تقرر شدة يقينهما بأن الخسران لازم إن لم تتداركهما المغفرة والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص74–84.","url":""}]},{"id":"s7-124","number":124,"surah":7,"verses":[24],"verseLabel":"الأعراف: 24","question":"لماذا جاء أمر الهبوط بصيغة الجمع: ﴿اهبطوا﴾ بعد خطاب آدم وزوجه؟","answer":"يشمل الجمع آدم وحواء وإبليس، وقيل ذريتهما تبعًا؛ فانتقل الخطاب من الزوجين إلى أطراف العداوة النازلة إلى الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص84–95.","url":""}]},{"id":"s7-125","number":125,"surah":7,"verses":[24],"verseLabel":"الأعراف: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿بعضكم لبعض عدو﴾، فأفرد ﴿عدو﴾؟","answer":"أفرد لأنه مصدر أو اسم جنس يصدق على الواحد والجمع، أو لأن كل بعض عدو للبعض الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص84–95.","url":""}]},{"id":"s7-126","number":126,"surah":7,"verses":[24],"verseLabel":"الأعراف: 24","question":"ما سرّ تقديم الاستقرار على المتاع: ﴿مستقر ومتاع إلى حين﴾؟","answer":"الاستقرار أساس إمكان الانتفاع، فقدم السبب والمحل ثم ذكر المتاع الحاصل فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص84–95.","url":""}]},{"id":"s7-127","number":127,"surah":7,"verses":[24],"verseLabel":"الأعراف: 24","question":"لماذا قُيد المتاع بـ﴿إلى حين﴾؟","answer":"لأن متاع الأرض مؤقت بالموت أو قيام الساعة؛ فالقيد يقطع توهم الدوام ويذكر بالمآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص84–95.","url":""}]},{"id":"s7-128","number":128,"surah":7,"verses":[24],"verseLabel":"الأعراف: 24","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿اهبطوا بعضكم لبعض عدو﴾ بصيغة الجمع، وفي طه: ﴿اهبطا منها جميعًا بعضكم لبعض عدو﴾ بصيغة التثنية؟","answer":"في الأعراف الخطاب لآدم وحواء وإبليس فناسب الجمع، وفي طه الخطاب لآدم وإبليس أو للفريقين فناسب التثنية، ثم عمّت العداوة الذرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص362–365.","url":""}]},{"id":"s7-129","number":129,"surah":7,"verses":[25],"verseLabel":"الأعراف: 25","question":"لماذا تكرر الظرف ﴿فيها﴾: ﴿فيها تحيون وفيها تموتون﴾؟","answer":"تكرار ﴿فيها﴾ يثبت اختصاص الأرض بمرحلتي الحياة والموت، ويقابل ذلك الخروج منها للبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص95–102.","url":""}]},{"id":"s7-130","number":130,"surah":7,"verses":[25],"verseLabel":"الأعراف: 25","question":"ما سرّ تقديم الحياة على الموت؟","answer":"قُدمت الحياة لأنها سابقة زمنًا وهي محل التكليف والعمل، ثم يأتي الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص95–102.","url":""}]},{"id":"s7-131","number":131,"surah":7,"verses":[25],"verseLabel":"الأعراف: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿ومنها تخرجون﴾، دون أن يقال: وفيها تبعثون؟","answer":"﴿منها تخرجون﴾ يصور البعث خروجًا محسوسًا من الأرض بعد الدفن، ويقابل ﴿فيها تموتون﴾ مقابلة مكانية بديعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص95–102.","url":""}]},{"id":"s7-132","number":132,"surah":7,"verses":[25],"verseLabel":"الأعراف: 25","question":"لماذا بُني ﴿تخرجون﴾ للمجهول؟","answer":"بُني للمجهول للاهتمام بحدث الخروج وهوله، وللعلم بأن مخرِجهم هو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص95–102.","url":""}]},{"id":"s7-133","number":133,"surah":7,"verses":[26],"verseLabel":"الأعراف: 26","question":"لماذا افتتح النداء بـ﴿يا بني آدم﴾ بعد قصة أبويهم؟","answer":"جاء النداء عقب قصة أبويهم لينقل العبرة إلى ذريتهما ويحذرهم من فتنة الشيطان، ويذكرهم بنعمة اللباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص102–119.","url":""}]},{"id":"s7-134","number":134,"surah":7,"verses":[26],"verseLabel":"الأعراف: 26","question":"لماذا عبّر عن خلق اللباس بقوله: ﴿أنزلنا عليكم لباسًا﴾؟","answer":"عُبر بالإنزال لأن مادته وأسبابه من رزق الله المنزل من السماء كالمطر، أو لأنه خلقه وقدره لهم؛ وفيه تعظيم للنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص102–119.","url":""}]},{"id":"s7-135","number":135,"surah":7,"verses":[26],"verseLabel":"الأعراف: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿يواري سوآتكم وريشًا﴾، فجمع بين الستر والريش؟","answer":"جمع بين الضرورة والزينة: لباس يستر العورة، وريش يجمّل الإنسان ويوسع عيشه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص102–119.","url":""}]},{"id":"s7-136","number":136,"surah":7,"verses":[26],"verseLabel":"الأعراف: 26","question":"لماذا سُميت الزينة ﴿ريشًا﴾؟","answer":"الريش في الأصل كسوة الطائر وزينته، فاستعير لما يتجمل به الإنسان من لباس ومال وهيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص102–119.","url":""}]},{"id":"s7-137","number":137,"surah":7,"verses":[26],"verseLabel":"الأعراف: 26","question":"لماذا عطف ﴿ولباس التقوى﴾، وهل التقوى لباس؟","answer":"استعير اللباس للتقوى لأنها تستر عيوب النفس وتحمي صاحبها من الفواحش والعذاب كما يستر الثوب الجسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص102–119.","url":""}]},{"id":"s7-138","number":138,"surah":7,"verses":[26],"verseLabel":"الأعراف: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك خير﴾ باسم الإشارة المفرد مع تعدد اللباس؟","answer":"الإشارة إلى لباس التقوى المفهوم بوصفه معنى واحدًا، أو إلى مجموع ما تقدم باعتباره المذكور؛ وهو خير من اللباس الظاهر وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص102–119.","url":""}]},{"id":"s7-139","number":139,"surah":7,"verses":[26],"verseLabel":"الأعراف: 26","question":"لماذا خُتمت بـ﴿لعلهم يذكرون﴾؟","answer":"الغاية أن يتذكر بنو آدم نعمة الستر وقصة أبويهم، فيختاروا لباس التقوى ويحذروا كشف الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص102–119.","url":""}]},{"id":"s7-140","number":140,"surah":7,"verses":[27],"verseLabel":"الأعراف: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يفتننكم الشيطان﴾، فنسب الفتنة إلى الشيطان مباشرة؟","answer":"أسندت الفتنة إليه لأنه سببها المباشر بالوسوسة والتزيين، والنهي منصب على تمكينه من إغوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص119–135.","url":""}]},{"id":"s7-141","number":141,"surah":7,"verses":[27],"verseLabel":"الأعراف: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿كما أخرج أبويكم من الجنة﴾، مع أن المخرج حقيقة هو الله؟","answer":"نُسب الإخراج إليه سببيًا؛ لأنه أغراهما بالأكل فكان فعله سبب الخروج، أما المخرج حقيقة فهو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص119–135.","url":""}]},{"id":"s7-142","number":142,"surah":7,"verses":[27],"verseLabel":"الأعراف: 27","question":"لماذا وصف آدم وحواء بـ﴿أبويكم﴾؟","answer":"سُميا أبويهم لأن البشر جميعًا من ذريتهما، وفي التعبير استثارة لعاطفة البنوة وأخذ العبرة من تجربتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص119–135.","url":""}]},{"id":"s7-143","number":143,"surah":7,"verses":[27],"verseLabel":"الأعراف: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿ينزع عنهما لباسهما ليريهما سوآتهما﴾؟","answer":"المضارع يصور مشهد النزع وكشف العورة، واللام تكشف غايته الخبيثة؛ وتحذّر الذرية من إعادة ما فعله بأبويهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص119–135.","url":""}]},{"id":"s7-144","number":144,"surah":7,"verses":[27],"verseLabel":"الأعراف: 27","question":"لماذا أكد: ﴿إنه يراكم هو وقبيله من حيث لا ترونهم﴾؟","answer":"أكد بـ﴿إن﴾ وضمير الفصل ﴿هو﴾ لأن خفاء الشياطين مظنة الغفلة عن مراقبتهم، فقرر تفاوت الرؤية الذي يقوي خطرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص119–135.","url":""}]},{"id":"s7-145","number":145,"surah":7,"verses":[27],"verseLabel":"الأعراف: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿من حيث لا ترونهم﴾، لا: وأنتم لا ترونهم؟","answer":"﴿من حيث﴾ تدل على جهة ووجه خفي لا تقع منه رؤيتهم أصلًا، فهي أبلغ من مجرد الحال ﴿وأنتم لا ترونهم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص119–135.","url":""}]},{"id":"s7-146","number":146,"surah":7,"verses":[27],"verseLabel":"الأعراف: 27","question":"لماذا خُتمت بـ﴿إنا جعلنا الشياطين أولياء للذين لا يؤمنون﴾؟","answer":"الختام يبين سبب تسلط الشياطين: توليهم عقوبة لمن لا يؤمن، ويحذر من أن عدم الإيمان يفضي إلى قبول ولايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص119–135.","url":""}]},{"id":"s7-147","number":147,"surah":7,"verses":[28],"verseLabel":"الأعراف: 28","question":"لماذا عبّر عن الفاحشة بالفعل: ﴿وإذا فعلوا فاحشة﴾، ثم احتجوا بالآباء والله؟","answer":"ذكر الفعل لإثبات وقوع الفاحشة وتجددها منهم، ثم حكى احتجاجهم بالتقليد ونسبة الأمر إلى الله، وهما حجتان باطلتان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص135–147.","url":""}]},{"id":"s7-148","number":148,"surah":7,"verses":[28],"verseLabel":"الأعراف: 28","question":"ما دلالة تقديم ﴿عليها﴾ في قولهم: ﴿وجدنا عليها آباءنا﴾؟","answer":"قُدّم ﴿عليها﴾ للاهتمام بالحال التي وجدوا آباءهم ملازمين لها، وتصوير شدة تعلقهم بالفاحشة وتقليدهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص135–147.","url":""}]},{"id":"s7-149","number":149,"surah":7,"verses":[28],"verseLabel":"الأعراف: 28","question":"لماذا فصل رد الدعويين فقال: ﴿إن الله لا يأمر بالفحشاء﴾ ثم استفهم؟","answer":"فُصل الرد لأن دعوى أمر الله أشد خطرًا؛ فنفاها أولًا نفيًا قاطعًا، ثم أنكر عليهم القول بلا علم، أما تقليد الآباء فبطلانه ظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص135–147.","url":""}]},{"id":"s7-150","number":150,"surah":7,"verses":[28],"verseLabel":"الأعراف: 28","question":"لماذا اختيرت ﴿الفحشاء﴾ في الرد، لا ﴿فاحشة﴾ كما في أول الآية؟","answer":"عُرفت ﴿الفحشاء﴾ للجنس، فنفى أن يأمر الله بأي شيء من جنس القبائح؛ وهو أعم وأقوى من إعادة فاحشة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص135–147.","url":""}]},{"id":"s7-151","number":151,"surah":7,"verses":[28],"verseLabel":"الأعراف: 28","question":"ما دلالة ختام الآية بقوله تعالى: ﴿أتقولون على الله ما لا تعلمون﴾؟","answer":"الاستفهام توبيخ وإنكار لنسبتهم التشريع إلى الله بغير برهان؛ فالقول عليه بلا علم أصل افترائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص135–147.","url":""}]},{"id":"s7-152","number":152,"surah":7,"verses":[29],"verseLabel":"الأعراف: 29","question":"لماذا قابل الفحشاء بقوله: ﴿قل أمر ربي بالقسط﴾؟","answer":"القسط ضد الفحشاء والظلم، فجاء الأمر به ردًا جامعًا يثبت أن تشريع الله قائم على العدل والاستقامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص147–160.","url":""}]},{"id":"s7-153","number":153,"surah":7,"verses":[29],"verseLabel":"الأعراف: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿أقيموا وجوهكم عند كل مسجد﴾، وهل الوجه هو الذي يقام؟","answer":"إقامة الوجه كناية عن التوجه الكامل وإخلاص القصد لله في الصلاة؛ فالوجه أشرف ما يظهر به اتجاه الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص147–160.","url":""}]},{"id":"s7-154","number":154,"surah":7,"verses":[29],"verseLabel":"الأعراف: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿عند كل مسجد﴾، لا: في كل مسجد؟","answer":"﴿عند﴾ تشمل حال العبادة وموضعها وزمانها، فلا تقصر إقامة الوجه على داخل بناء المسجد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص147–160.","url":""}]},{"id":"s7-155","number":155,"surah":7,"verses":[29],"verseLabel":"الأعراف: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿وادعوه مخلصين له الدين﴾، فقدم ﴿له﴾؟","answer":"قُدّم ﴿له﴾ للاختصاص: يكون الدين والدعاء خالصين لله وحده، لا نصيب فيهما لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص147–160.","url":""}]},{"id":"s7-156","number":156,"surah":7,"verses":[29],"verseLabel":"الأعراف: 29","question":"لماذا شُبه البعث بالبدء: ﴿كما بدأكم تعودون﴾؟","answer":"كما قدر على إنشاء الخلق أول مرة يعيدهم بعد الموت؛ فالتشبيه حجة ببدء الخلق على إمكان البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص147–160.","url":""}]},{"id":"s7-157","number":157,"surah":7,"verses":[30],"verseLabel":"الأعراف: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿فريقًا هدى وفريقًا حق عليهم الضلالة﴾، فغيّر البناء بين الفريقين؟","answer":"أسند الهدى إلى الله تشريفًا وفضلًا، أما الضلالة فبُنيت على استحقاقهم لها بسبب اختيارهم ولاية الشياطين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص160–169.","url":""}]},{"id":"s7-158","number":158,"surah":7,"verses":[30],"verseLabel":"الأعراف: 30","question":"ما سرّ تقديم المفعول ﴿فريقًا﴾ في الجملتين؟","answer":"قُدّم للاهتمام بتقسيم الناس فريقين، ولإبراز المقابلة بين مآلهما قبل ذكر الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص160–169.","url":""}]},{"id":"s7-159","number":159,"surah":7,"verses":[30],"verseLabel":"الأعراف: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿حق عليهم الضلالة﴾، لا: أضلهم؟","answer":"﴿حق﴾ تفيد ثبوت الضلالة واستحقاقها ولزومها لهم بعد أسبابها، لا نسبة الإضلال إليهم بلا بيان لمسؤوليتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص160–169.","url":""}]},{"id":"s7-160","number":160,"surah":7,"verses":[30],"verseLabel":"الأعراف: 30","question":"لماذا عُلّلت ضلالتهم باتخاذ الشياطين ﴿أولياء من دون الله﴾؟","answer":"لأن اتخاذ الشيطان وليًا وترك ولاية الله هو السبب الاختياري الذي أورثهم الضلالة واستحقاقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص160–169.","url":""}]},{"id":"s7-161","number":161,"surah":7,"verses":[30],"verseLabel":"الأعراف: 30","question":"لماذا خُتمت بـ﴿ويحسبون أنهم مهتدون﴾؟","answer":"الختام يصور أخطر الضلال: أن يجتمع الانحراف مع اعتقاد الهداية، فلا يراجع صاحبه نفسه ولا يطلب الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص160–169.","url":""}]},{"id":"s7-162","number":162,"surah":7,"verses":[31],"verseLabel":"الأعراف: 31","question":"لماذا تكرر نداء ﴿يا بني آدم﴾؟","answer":"تكرر النداء لاستقلال الوصية الجديدة وعظمها، ولاستحضار انتسابهم إلى آدم بعد التحذير من فتنة الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص169–181.","url":""}]},{"id":"s7-163","number":163,"surah":7,"verses":[31],"verseLabel":"الأعراف: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿خذوا زينتكم عند كل مسجد﴾، دون أن يقال: البسوا ثيابكم؟","answer":"الأخذ أبلغ من اللبس؛ فهو أمر بتحصيل الزينة واستعمالها والعناية بها عند العبادة، ويشمل ما وراء مجرد الثياب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص169–181.","url":""}]},{"id":"s7-164","number":164,"surah":7,"verses":[31],"verseLabel":"الأعراف: 31","question":"لماذا أضاف الزينة إليهم: ﴿زينتكم﴾؟","answer":"الإضافة تفيد أن ما يتزينون به مباح لهم ومهيأ لمصلحتهم، وفيها رد على من حرموا على أنفسهم اللباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص169–181.","url":""}]},{"id":"s7-165","number":165,"surah":7,"verses":[31],"verseLabel":"الأعراف: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿عند كل مسجد﴾، لا: في المسجد؟","answer":"﴿عند﴾ تشمل كل حال صلاة وسجود وموضعهما، و﴿كل﴾ تعمم المساجد والصلوات، بخلاف حصره في مسجد معين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص169–181.","url":""}]},{"id":"s7-166","number":166,"surah":7,"verses":[31],"verseLabel":"الأعراف: 31","question":"لماذا جمع بين ﴿كلوا واشربوا﴾ وبين أخذ الزينة للمسجد؟","answer":"جمع بينهما لإبطال تحريم المشركين اللباس والطعام في النسك، وإقرار نعم الجسد والزينة ضمن حدود الاعتدال.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص169–181.","url":""}]},{"id":"s7-167","number":167,"surah":7,"verses":[31],"verseLabel":"الأعراف: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تسرفوا﴾ بعد إباحة الأكل والشرب؟","answer":"جاء النهي عقب الإباحة حتى لا تنقلب النعمة إلى تجاوز؛ فالمشروع الانتفاع بلا تبذير ولا تعد لحد الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص169–181.","url":""}]},{"id":"s7-168","number":168,"surah":7,"verses":[31],"verseLabel":"الأعراف: 31","question":"لماذا خُتمت بـ﴿إنه لا يحب المسرفين﴾، لا: إنه يعاقبهم؟","answer":"نفي المحبة أبلغ في التربية؛ لأنه يبين أن الإسراف وصف مبغوض يحرم صاحبه قرب الله، ويتضمن الوعيد دون الاقتصار على العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص169–181.","url":""}]},{"id":"s7-169","number":169,"surah":7,"verses":[32],"verseLabel":"الأعراف: 32","question":"ما دلالة الإنكار في قوله تعالى: ﴿قل من حرم زينة الله﴾؟","answer":"الاستفهام للإنكار: لا يملك أحد تحريم ما أباحه الله من الزينة والرزق؛ وفيه إبطال تشريع المشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص181–198.","url":""}]},{"id":"s7-170","number":170,"surah":7,"verses":[32],"verseLabel":"الأعراف: 32","question":"لماذا أضيفت الزينة إلى الله: ﴿زينة الله﴾؟","answer":"إضافتها إليه لأنها خلقه وعطيته وتشريعه لعباده، فلا يملك غيره تحريمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص181–198.","url":""}]},{"id":"s7-171","number":171,"surah":7,"verses":[32],"verseLabel":"الأعراف: 32","question":"ما سرّ التعبير في قوله تعالى: ﴿التي أخرج لعباده﴾، فعبّر عن خلق الزينة بالإخراج؟","answer":"الإخراج تصوير لإبراز الزينة من أسبابها وإظهارها للعباد بعد أن كانت كامنة في موادها، وفيه معنى العناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص181–198.","url":""}]},{"id":"s7-172","number":172,"surah":7,"verses":[32],"verseLabel":"الأعراف: 32","question":"لماذا جمع بين الزينة و﴿الطيبات من الرزق﴾؟","answer":"الزينة تصلح الظاهر وتجمله، والطيبات تقوم البدن وتلذه؛ فجمع نوعي النعمة ودفع تحريم المشركين لهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص181–198.","url":""}]},{"id":"s7-173","number":173,"surah":7,"verses":[32],"verseLabel":"الأعراف: 32","question":"ما سرّ التعبير في قوله تعالى: ﴿قل هي للذين آمنوا في الحياة الدنيا﴾ مع انتفاع الكافرين بها؟","answer":"هي مخلوقة أصلًا لينتفع بها المؤمنون في الدنيا، ويشاركهم غيرهم تبعًا وابتلاءً؛ فاللام لبيان الأحقية والقصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص181–198.","url":""}]},{"id":"s7-174","number":174,"surah":7,"verses":[32],"verseLabel":"الأعراف: 32","question":"ما سرّ التعبير في قوله تعالى: ﴿خالصة يوم القيامة﴾، دون أن يقال: وهي لهم في الآخرة؟","answer":"﴿خالصة﴾ تنفي مشاركة الكافرين فيها يوم القيامة وتنفي ما يشوب نعيم الدنيا من كدر وزوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص181–198.","url":""}]},{"id":"s7-175","number":175,"surah":7,"verses":[32],"verseLabel":"الأعراف: 32","question":"لماذا خُتمت بـ﴿كذلك نفصل الآيات لقوم يعلمون﴾؟","answer":"كما فُصل حكم الزينة والطيبات تفصل الآيات؛ وخص أهل العلم لأنهم الذين يدركون حدود الحلال ويعملون بالدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص181–198.","url":""}]},{"id":"s7-176","number":176,"surah":7,"verses":[33],"verseLabel":"الأعراف: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿إنما حرم ربي﴾ بطريق القصر بعد سؤال ﴿من حرم﴾؟","answer":"القصر يبين أن التحريم لله وحده وأن محرماته هي المذكورة، لا ما ابتدعه المشركون من الزينة والطيبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص198–211.","url":""}]},{"id":"s7-177","number":177,"surah":7,"verses":[33],"verseLabel":"الأعراف: 33","question":"لماذا بدأ المحرمات بـ﴿الفواحش ما ظهر منها وما بطن﴾؟","answer":"بدأ بها لشناعتها واتصالها بما قبلها من طوافهم عراة، وشمل ظاهرها وباطنها لاستيعاب أفعال الجوارح والقلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص198–211.","url":""}]},{"id":"s7-178","number":178,"surah":7,"verses":[33],"verseLabel":"الأعراف: 33","question":"لماذا عطف ﴿الإثم والبغي بغير الحق﴾، وما الفرق بينهما؟","answer":"الإثم ما يوجب الذم والعقوبة ويشمل المعاصي، والبغي تجاوز على حقوق الغير بالظلم والاستطالة؛ فعطف الخاص المتميز على العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص198–211.","url":""}]},{"id":"s7-179","number":179,"surah":7,"verses":[33],"verseLabel":"الأعراف: 33","question":"لماذا قُيّد البغي بـ﴿بغير الحق﴾ مع أن البغي لا يكون بحق؟","answer":"القيد للتشنيع والكشف عن بطلانه، أو للاحتراز عما يشبه البغي صورة وهو استيفاء الحق المشروع؛ فليس كل طلب أو غلبة مذمومًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص198–211.","url":""}]},{"id":"s7-180","number":180,"surah":7,"verses":[33],"verseLabel":"الأعراف: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿أن تشركوا بالله ما لم ينزل به سلطانًا﴾، فجعل الحجة سلطانًا ينزل؟","answer":"شُبه البرهان بالسلطان لقوته وغلبته على الخصم، ووصفه بالإنزال لأن الحجة المقبولة في العقيدة لا تكون إلا من وحي الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص198–211.","url":""}]},{"id":"s7-181","number":181,"surah":7,"verses":[33],"verseLabel":"الأعراف: 33","question":"لماذا جعل القول على الله بلا علم خاتمة المحرمات؟","answer":"جُعل خاتمة لأنه أصل عظيم تنشأ عنه البدع والتحليل والتحريم والشرك؛ ومن افترى على الله جمع أنواع الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص198–211.","url":""}]},{"id":"s7-182","number":182,"surah":7,"verses":[34],"verseLabel":"الأعراف: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكل أمة أجل﴾، فأضاف الأجل إلى الأمة لا إلى أفرادها؟","answer":"المراد أجل الجماعة في بقائها أو حلول عقوبتها، فالأمم لها سنن وآجال كما للأفراد آجال، والسياق في وعيد الجماعات المكذبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-183","number":183,"surah":7,"verses":[34],"verseLabel":"الأعراف: 34","question":"لماذا نُكّرت ﴿أمة﴾ و﴿أجل﴾؟","answer":"تنكير ﴿أمة﴾ للعموم: كل أمة، وتنكير ﴿أجل﴾ لبيان أن لكل منها وقتًا مقدرًا مخصوصًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-184","number":184,"surah":7,"verses":[34],"verseLabel":"الأعراف: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا جاء أجلهم﴾، فجعل الأجل آتيًا؟","answer":"شُبه الأجل بغائب يأتي عند حلول وقته، فيصور حتميته وأنه يوافيهم لا محالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-185","number":185,"surah":7,"verses":[34],"verseLabel":"الأعراف: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يستأخرون ساعة ولا يستقدمون﴾؟","answer":"ينفي أدنى تغيير في الموعد من الجهتين؛ فلا تأخير للبقاء ولا تقديم قبل الوقت المقدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-186","number":186,"surah":7,"verses":[34],"verseLabel":"الأعراف: 34","question":"ما سرّ تقديم الاستئخار على الاستقدام؟","answer":"قُدم الاستئخار لأنه مطلوب من الناس عند نزول الأجل، أما الاستقدام فلا يطلبونه عادة؛ فبدأ بما هو أهم في المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-187","number":187,"surah":7,"verses":[34],"verseLabel":"الأعراف: 34","question":"لماذا نُكرت ﴿ساعة﴾؟","answer":"نُكرت للتقليل: لا يتأخرون أقل جزء من الزمن، فضلًا عن مدة طويلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-188","number":188,"surah":7,"verses":[34],"verseLabel":"الأعراف: 34","question":"ما سرّ انتقال الفاء في الأعراف والنحل إلى صدر الشرط: ﴿فإذا جاء أجلهم لا يستأخرون﴾، وبقائها في جواب الشرط في يونس: ﴿إذا جاء أجلهم فلا يستأخرون﴾؟","answer":"الفاء في الأعراف والنحل فصيحة تفرع حلول الأجل على السياق السابق؛ أما يونس فجيء بالشرط غير متفرع، ثم دخلت الفاء في جوابه لتقوية لزوم عدم التأخر للمجيء.","sources":[{"label":"إسلام ويب: سبب إثبات الفاء وحذفها.","url":""}]},{"id":"s7-189","number":189,"surah":7,"verses":[35],"verseLabel":"الأعراف: 35","question":"لماذا تكرر نداء ﴿يا بني آدم﴾ للمرة الثالثة؟","answer":"تكرر النداء لاستقلال عهد الرسل عما قبله، وتجديد تنبيه بني آدم إلى طريق النجاة بعد بيان الأجل والمصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-190","number":190,"surah":7,"verses":[35],"verseLabel":"الأعراف: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿إما يأتينكم رسل منكم﴾ مع تحقق مجيء الرسل؟","answer":"﴿إن﴾ هنا لتفصيل ما سيقع بحسب أفراد المخاطبين أو على معنى الشرط الذي تواجهه كل أمة، لا للشك في أصل إرسال الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-191","number":191,"surah":7,"verses":[35],"verseLabel":"الأعراف: 35","question":"لماذا أكد فعل المجيء بنون التوكيد؟","answer":"النون تؤكد حتمية وصول الرسل والبلاغ إلى المخاطبين، وتلائم مقام العهد والتحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-192","number":192,"surah":7,"verses":[35],"verseLabel":"الأعراف: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿رسل منكم﴾؟","answer":"﴿منكم﴾ تؤنسهم بالرسل وتجعل الحجة أبلغ؛ فهم بشر يعرفون لسان قومهم وأحوالهم ويمكن الاقتداء بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-193","number":193,"surah":7,"verses":[35],"verseLabel":"الأعراف: 35","question":"لماذا عبّر عن تبليغ الوحي بقوله: ﴿يقصون عليكم آياتي﴾؟","answer":"القص إخبار منظم متتابع؛ فصور تبليغ الآيات وبيانها لهم كقص الخبر شيئًا بعد شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-194","number":194,"surah":7,"verses":[35],"verseLabel":"الأعراف: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن اتقى وأصلح﴾، دون أن يقال: آمن وعمل صالحًا؟","answer":"التقوى تجمع ترك التكذيب والاستكبار، والإصلاح يجمع تصحيح العمل وما أفسده الإنسان؛ فهما جواب مباشر لآفات السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-195","number":195,"surah":7,"verses":[35],"verseLabel":"الأعراف: 35","question":"لماذا نُفي الخوف ثم الحزن: ﴿فلا خوف عليهم ولا هم يحزنون﴾؟","answer":"نُفي الخوف من المستقبل أولًا، ثم الحزن على الماضي؛ فاستوعب أمنهم من آلام الزمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-196","number":196,"surah":7,"verses":[36],"verseLabel":"الأعراف: 36","question":"لماذا قابل المتقين بـ﴿الذين كذبوا بآياتنا واستكبروا عنها﴾؟","answer":"لأنهما يقابلان ﴿اتقى وأصلح﴾: التكذيب فساد الاعتقاد، والاستكبار امتناع عن الانقياد والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-197","number":197,"surah":7,"verses":[36],"verseLabel":"الأعراف: 36","question":"لماذا عُدّي الاستكبار بـ﴿عنها﴾؟","answer":"عُدي بـ﴿عن﴾ لأن الاستكبار يتضمن الإعراض والتباعد عن الآيات وعدم الانقياد لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-198","number":198,"surah":7,"verses":[36],"verseLabel":"الأعراف: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿أولئك أصحاب النار﴾، فجعلهم أصحابًا لها؟","answer":"الصاحب ملازم لصاحبه؛ فالتعبير يدل على ملازمتهم النار وعدم انفكاكهم عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-199","number":199,"surah":7,"verses":[36],"verseLabel":"الأعراف: 36","question":"لماذا أظهر الضمير: ﴿هم فيها خالدون﴾؟","answer":"ضمير الفصل يقوي الحكم ويفيد الاختصاص: هم المخلدون فيها، لا مجرد دخول عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص211–238.","url":""}]},{"id":"s7-200","number":200,"surah":7,"verses":[37],"verseLabel":"الأعراف: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن أظلم ممن افترى على الله كذبًا أو كذب بآياته﴾؟","answer":"الاستفهام للإنكار والنفي: لا أشد ظلمًا ممن اختلق على الله قولًا أو رد آياته؛ فجمع إنشاء الباطل وتكذيب الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص238–254.","url":""}]},{"id":"s7-201","number":201,"surah":7,"verses":[37],"verseLabel":"الأعراف: 37","question":"لماذا عطف الافتراء والتكذيب بـ﴿أو﴾؟","answer":"جاءت ﴿أو﴾ للتقسيم: فالظلم يتحقق بأي واحد من الأمرين، إنشاء الكذب على الله أو تكذيب آياته، وقد يجتمعان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص238–254.","url":""}]},{"id":"s7-202","number":202,"surah":7,"verses":[37],"verseLabel":"الأعراف: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿ينالهم نصيبهم من الكتاب﴾، وما المقصود بالكتاب؟","answer":"النيل يصور وصول المقدّر إليهم حتمًا؛ والكتاب هو ما كتب لهم في اللوح من رزق وأجل وعمل أو نصيبهم من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص238–254.","url":""}]},{"id":"s7-203","number":203,"surah":7,"verses":[37],"verseLabel":"الأعراف: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا جاءتهم رسلنا يتوفونهم﴾، فجمع الرسل؟","answer":"المراد رسل الموت من الملائكة: ملك الموت وأعوانه؛ فالجمع باعتبار تعدد الملائكة الموكلين بالتوفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص238–254.","url":""}]},{"id":"s7-204","number":204,"surah":7,"verses":[37],"verseLabel":"الأعراف: 37","question":"ما دلالة سؤال الملائكة: ﴿أين ما كنتم تدعون من دون الله﴾؟","answer":"سؤال توبيخ وتقرير يظهر عجز المعبودات التي دعوها؛ لا طلبًا لعلم مكانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص238–254.","url":""}]},{"id":"s7-205","number":205,"surah":7,"verses":[37],"verseLabel":"الأعراف: 37","question":"ما دلالة جوابهم: ﴿ضلوا عنا﴾، وتصوير غياب آلهتهم بالضلال؟","answer":"أي غابوا وفقدوا فلم ينفعوا؛ فصور بطلان أثرهم كضياع من كانوا يرجون حضورهم ونصرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص238–254.","url":""}]},{"id":"s7-206","number":206,"surah":7,"verses":[37],"verseLabel":"الأعراف: 37","question":"ما دلالة شهادتهم ﴿على أنفسهم أنهم كانوا كافرين﴾؟","answer":"شهدوا حين قامت الحجة وعاينوا الحق، فصار اعترافهم بالكفر إقرارًا على أنفسهم لا ينفعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص238–254.","url":""}]},{"id":"s7-207","number":207,"surah":7,"verses":[38],"verseLabel":"الأعراف: 38","question":"ما سرّ التعبير بقوله تعالى: ﴿ادخلوا في أمم قد خلت من قبلكم﴾، ولم يقل: مع أمم؟","answer":"﴿في﴾ تفيد إدخالهم ضمن جماعات سبقتهم واستقرارهم في جملتها داخل النار، وهو أقوى من مجرد المصاحبة بـ«مع».","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص254–270.","url":""}]},{"id":"s7-208","number":208,"surah":7,"verses":[38],"verseLabel":"الأعراف: 38","question":"لماذا جمع الجن والإنس في دخول النار؟","answer":"جمع الفريقين لأن التكليف والعصيان وقعا منهما، ولأن شياطين الجن وأتباعهم من الإنس اشتركوا في الإضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص254–270.","url":""}]},{"id":"s7-209","number":209,"surah":7,"verses":[38],"verseLabel":"الأعراف: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿كلما دخلت أمة لعنت أختها﴾، وسمى الأمة الأخرى أختًا؟","answer":"سميت أختها لاشتراكهما في الملة والكفر والمصير، مع أن هذا الاشتراك لم يمنع التلاعن.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص254–270.","url":""}]},{"id":"s7-210","number":210,"surah":7,"verses":[38],"verseLabel":"الأعراف: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا اداركوا فيها جميعًا﴾، واختار صيغة الادّارك؟","answer":"الادّراك تتابع اللحاق حتى يجتمع آخرهم بأولهم في النار؛ وصيغته تصور تدارك بعضهم بعضًا واجتماعهم جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص254–270.","url":""}]},{"id":"s7-211","number":211,"surah":7,"verses":[38],"verseLabel":"الأعراف: 38","question":"لماذا سمت الأمة المتبوعة ﴿أولاهم﴾ والتابعة ﴿أخراهم﴾؟","answer":"الأولى المتقدمة زمانًا والمتبوعة في الضلال، والأخرى المتأخرة التابعة التي جاءت بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص254–270.","url":""}]},{"id":"s7-212","number":212,"surah":7,"verses":[38],"verseLabel":"الأعراف: 38","question":"لماذا طلب الأتباع للمتبوعين ﴿عذابًا ضعفًا﴾؟","answer":"لأنهم أضلوهم وزينوا لهم الباطل، فطلبوا أن يجمع لهم عذاب ضلالهم وعذاب إضلال غيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص254–270.","url":""}]},{"id":"s7-213","number":213,"surah":7,"verses":[38],"verseLabel":"الأعراف: 38","question":"لماذا جاء الرد: ﴿لكل ضعف ولكن لا تعلمون﴾؟","answer":"لكل فريق عذاب مضاعف: للمتبوع بسبب الإضلال، وللتابع بسبب اتباع الباطل مع قيام الحجة؛ لكنهم لا يحيطون بمقاديره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص254–270.","url":""}]},{"id":"s7-214","number":214,"surah":7,"verses":[39],"verseLabel":"الأعراف: 39","question":"ما دلالة قول الأولى للأخرى: ﴿فما كان لكم علينا من فضل﴾؟","answer":"نفوا مزية الأتباع عليهم في استحقاق التخفيف؛ فقد اشترك الجميع في الكفر ولم تكن للتابعين حجة ترفع عنهم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص270–278.","url":""}]},{"id":"s7-215","number":215,"surah":7,"verses":[39],"verseLabel":"الأعراف: 39","question":"لماذا عبّر عن زيادة العذاب بـ﴿فضل﴾؟","answer":"استعمل تهكمًا على معنى الزيادة والمزية: لا فضل لكم علينا يوجب تخفيف عذابكم أو زيادة عذابنا دونكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص270–278.","url":""}]},{"id":"s7-216","number":216,"surah":7,"verses":[39],"verseLabel":"الأعراف: 39","question":"لماذا خُتم الحوار بـ﴿فذوقوا العذاب بما كنتم تكسبون﴾؟","answer":"الخطاب يقطع جدالهم ورد التبعة بعضهم على بعض؛ فكل فريق يذوق جزاء ما كان يكتسبه باختياره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص270–278.","url":""}]},{"id":"s7-217","number":217,"surah":7,"verses":[35],"verseLabel":"الأعراف: 39؛ الأنفال: 35","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿بما كنتم تكسبون﴾، وفي الأنفال: ﴿بما كنتم تكفرون﴾؟","answer":"في الأعراف خُتم بمطلق الكسب لأن السياق يعدد أعمال الفريقين ومسؤوليتهم عنها، وفي الأنفال صُرح بالكفر لأن الآية في عذاب الكافرين وعبادتهم عند البيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، مادة الأنفال: 35؛ ابن عاشور، التحرير والتنوير، 9/340.","url":""}]},{"id":"s7-218","number":218,"surah":7,"verses":[40],"verseLabel":"الأعراف: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تفتح لهم أبواب السماء﴾، وما الذي كان ينتظر أن يصعد؟","answer":"لا تفتح لصعود أرواحهم أو أعمالهم ودعائهم، ولا لنزول الرحمة عليهم؛ فالعبارة تصور حرمانهم من القبول والكرامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص278–290.","url":""}]},{"id":"s7-219","number":219,"surah":7,"verses":[40],"verseLabel":"الأعراف: 40","question":"لماذا جُمعت ﴿أبواب السماء﴾؟","answer":"جمعها لتصوير إحكام الإغلاق من كل جهة، أو لأن للسماء أبوابًا متعددة تصعد منها الأعمال والأرواح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص278–290.","url":""}]},{"id":"s7-220","number":220,"surah":7,"verses":[40],"verseLabel":"الأعراف: 40","question":"لماذا شُبّه استحالة دخولهم الجنة بولوج الجمل في سم الخياط؟","answer":"مثل لاستحالة دخولهم الجنة: دخول أعظم جسم مألوف في أضيق ثقب مألوف محال عادة، وكذلك دخولهم ما داموا على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص278–290.","url":""}]},{"id":"s7-221","number":221,"surah":7,"verses":[40],"verseLabel":"الأعراف: 40","question":"لماذا اختير ﴿الجمل﴾ و﴿سم الخياط﴾؟","answer":"الجمل مشهور بعظم الجرم، وسم الخياط غاية في الضيق؛ فاجتماعهما يصنع أوضح صورة للتعذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص278–290.","url":""}]},{"id":"s7-222","number":222,"surah":7,"verses":[40],"verseLabel":"الأعراف: 40","question":"لماذا خُتمت بـ﴿وكذلك نجزي المجرمين﴾، لا: المكذبين؟","answer":"المجرم أعم وصفًا لمن اكتسب الجريمة واستحق العقوبة؛ فالتذييل يجعل هذا الجزاء سنة في كل مجرم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص278–290.","url":""}]},{"id":"s7-223","number":223,"surah":7,"verses":[41],"verseLabel":"الأعراف: 41","question":"ما سرّ وصف جهنم بأنها ﴿مهاد﴾ مع أن المهاد موضع الراحة؟","answer":"وصف جهنم بالمهاد تهكم ومقابلة؛ فما يفترشونه ليس موضع راحة بل نار تحيط بهم من أسفل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص290–297.","url":""}]},{"id":"s7-224","number":224,"surah":7,"verses":[41],"verseLabel":"الأعراف: 41","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن فوقهم غواش﴾، فحذف وصف ما يغشاهم؟","answer":"حذف الموصوف للتهويل والتعميم: فوقهم أغطية كثيرة من النار أو العذاب تغشاهم، فتركها مبهمة ليذهب الذهن كل مذهب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص290–297.","url":""}]},{"id":"s7-225","number":225,"surah":7,"verses":[41],"verseLabel":"الأعراف: 41","question":"لماذا جُمعت ﴿غواش﴾ ونُكرت؟","answer":"الجمع لتعدد طبقات ما يغشاهم، والتنكير للتكثير والتهويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص290–297.","url":""}]},{"id":"s7-226","number":226,"surah":7,"verses":[41],"verseLabel":"الأعراف: 41","question":"لماذا خُتمت بـ﴿وكذلك نجزي الظالمين﴾ بعد ﴿المجرمين﴾ في الآية السابقة؟","answer":"ذكر المجرمين في حرمان الجنة، ثم الظالمين عند إحاطة النار؛ والظلم يبين سبب الجزاء وهو وضع الحق في غير موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص290–297.","url":""}]},{"id":"s7-227","number":227,"surah":7,"verses":[42],"verseLabel":"الأعراف: 42","question":"لماذا اعترض بين الإيمان والجنة بقوله: ﴿لا نكلف نفسًا إلا وسعها﴾؟","answer":"الجملة اعتراض يرفع توهم أن العمل الصالح المطلوب فوق الطاقة؛ فدخول الجنة مرتب على إيمان وعمل في حدود الوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص297–306.","url":""}]},{"id":"s7-228","number":228,"surah":7,"verses":[42],"verseLabel":"الأعراف: 42","question":"لماذا نُكرت ﴿نفسًا﴾ و﴿وسعها﴾؟","answer":"﴿نفسًا﴾ للعموم: لا نفس أيًا كانت، و﴿وسعها﴾ يخصص التكليف بقدر الطاقة المختلفة لكل نفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص297–306.","url":""}]},{"id":"s7-229","number":229,"surah":7,"verses":[42],"verseLabel":"الأعراف: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿أولئك أصحاب الجنة﴾ في مقابل أصحاب النار؟","answer":"كما لازم أهل النار نارهم، يلازم المؤمنون الجنة؛ وفي المقابلة تمام تصوير المآلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص297–306.","url":""}]},{"id":"s7-230","number":230,"surah":7,"verses":[43],"verseLabel":"الأعراف: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿ونزعنا ما في صدورهم من غل﴾، فجعل الغل شيئًا يُنزع؟","answer":"استعير النزع لإزالة الغل إزالة تامة قوية؛ كأنه جسم متغلغل في الصدور يُقتلع منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص306–321.","url":""}]},{"id":"s7-231","number":231,"surah":7,"verses":[43],"verseLabel":"الأعراف: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿ما في صدورهم من غل﴾، دون أن يقال: غلهم؟","answer":"الموصول و﴿من﴾ البيانية يعمان كل ما يمكن أن يوجد في الصدور من غل، لا غلًا معينًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص306–321.","url":""}]},{"id":"s7-232","number":232,"surah":7,"verses":[43],"verseLabel":"الأعراف: 43","question":"ما سرّ تقديم تطهير الصدور على جريان الأنهار؟","answer":"طهر باطنهم أولًا ليكمل نعيم الاجتماع، ثم ذكر جريان الأنهار وهو نعيم الظاهر؛ فسلامة الصدر أصل الراحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص306–321.","url":""}]},{"id":"s7-233","number":233,"surah":7,"verses":[43],"verseLabel":"الأعراف: 43","question":"ما دلالة قول أهل الجنة: ﴿الحمد لله الذي هدانا لهذا﴾، وإلام يشير ﴿هذا﴾؟","answer":"يشير ﴿هذا﴾ إلى ما هم فيه من الجنة والنعيم أو إلى طريقه؛ فحمدوا الله على الهداية التي أوصلتهم إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص306–321.","url":""}]},{"id":"s7-234","number":234,"surah":7,"verses":[43],"verseLabel":"الأعراف: 43","question":"ما سرّ قولهم: ﴿وما كنا لنهتدي لولا أن هدانا الله﴾ باللام و﴿لولا﴾؟","answer":"اللام لتوكيد نفي قدرتهم على الاهتداء من أنفسهم، و﴿لولا﴾ تجعل هداية الله شرطًا لازمًا؛ فاعترفوا بأن الفضل كله له.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص306–321.","url":""}]},{"id":"s7-235","number":235,"surah":7,"verses":[43],"verseLabel":"الأعراف: 43","question":"ما مناسبة قولهم: ﴿لقد جاءت رسل ربنا بالحق﴾ بعد دخول الجنة؟","answer":"قالوه تصديقًا للرسل بعد مشاهدة الموعود، وفرحًا بتحقق خبرهم، وشكرًا لربهم على الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص306–321.","url":""}]},{"id":"s7-236","number":236,"surah":7,"verses":[43],"verseLabel":"الأعراف: 43","question":"لماذا نودوا: ﴿أن تلكم الجنة أورثتموها﴾، فجعلت الجنة ميراثًا؟","answer":"شُبه تمليكهم الجنة بالميراث لأنه ملك ثابت آل إليهم بلا زوال، أو لأنهم ورثوا منازل أعدت لهم أو تركها غيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص306–321.","url":""}]},{"id":"s7-237","number":237,"surah":7,"verses":[43],"verseLabel":"الأعراف: 43","question":"ما سرّ الجمع بين ﴿أورثتموها﴾ و﴿بما كنتم تعملون﴾؟","answer":"العمل سبب للدخول بتفضل الله، أما نفس الجنة وثوابها فميراث وفضل؛ فلا تعارض بين السببية والمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص306–321.","url":""}]},{"id":"s7-238","number":238,"surah":7,"verses":[44],"verseLabel":"الأعراف: 44","question":"لماذا نادى أصحاب الجنة أصحاب النار؟","answer":"نادوهم لإقامة الحجة وإظهار صدق وعد الله للفريقين، وزيادة الحسرة على المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص321–341.","url":""}]},{"id":"s7-239","number":239,"surah":7,"verses":[44],"verseLabel":"الأعراف: 44","question":"ما سرّ إضافة الوعد إلى الرب في قول الفريقين: ﴿ما وعدنا ربنا﴾؟","answer":"أضاف أهل الجنة الوعد إلى ﴿ربنا﴾ اعترافًا بفضله وتربيته، وجاء خطاب أهل النار بـ﴿ربكم﴾ إلزامًا لهم بمن كذبوا وعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص321–341.","url":""}]},{"id":"s7-240","number":240,"surah":7,"verses":[44],"verseLabel":"الأعراف: 44","question":"لماذا سأل أهل الجنة: ﴿فهل وجدتم ما وعد ربكم حقًا﴾ وهم يعلمون؟","answer":"السؤال للتقرير والتبكيت، ليقر أهل النار بألسنتهم بصدق الوعيد كما أقر أهل الجنة بصدق الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص321–341.","url":""}]},{"id":"s7-241","number":241,"surah":7,"verses":[44],"verseLabel":"الأعراف: 44","question":"لماذا أجاب أهل النار بكلمة واحدة: ﴿نعم﴾؟","answer":"اختصروا لشدة الحال ووضوح الحق وانقطاع الحجة؛ فلم يملكوا إلا الإقرار بكلمة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص321–341.","url":""}]},{"id":"s7-242","number":242,"surah":7,"verses":[44],"verseLabel":"الأعراف: 44","question":"ما سرّ التعبير بقوله تعالى: ﴿فأذن مؤذن بينهم﴾، ولم يُسمّ المؤذن؟","answer":"بُني للمجهول لأن العبرة بالإعلان ومضمونه لا بشخص المنادي، وقيل هو ملك؛ فإبهامه يزيد جلال الموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص321–341.","url":""}]},{"id":"s7-243","number":243,"surah":7,"verses":[44],"verseLabel":"الأعراف: 44","question":"لماذا كانت اللعنة ﴿على الظالمين﴾ لا على الكافرين؟","answer":"الظلم أعم ويكشف أصل كفرهم وصدهم وافترائهم؛ فاستحقوا اللعنة لما جمعوه من أنواع الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص321–341.","url":""}]},{"id":"s7-244","number":244,"surah":7,"verses":[45],"verseLabel":"الأعراف: 45","question":"لماذا وصف الظالمين بأنهم ﴿يصدون عن سبيل الله ويبغونها عوجًا﴾؟","answer":"هذه أوصاف تكشف تعدي ظلمهم إلى غيرهم: يمنعون الناس من طريق الله، ويحاولون إظهاره معوجًا لصدهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص341–353.","url":""}]},{"id":"s7-245","number":245,"surah":7,"verses":[45],"verseLabel":"الأعراف: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿يبغونها عوجًا﴾، فجعل العوج مطلوبًا؟","answer":"صورهم كأنهم يطلبون العوج ويبتغونه للسبيل المستقيم؛ أي يلتمسون الشبه ويصفونه بالانحراف أو يريدون الناس عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص341–353.","url":""}]},{"id":"s7-246","number":246,"surah":7,"verses":[45],"verseLabel":"الأعراف: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم بالآخرة كافرون﴾ بتقديم ﴿بالآخرة﴾؟","answer":"قُدّم للاهتمام بموضع كفرهم وتشنيعه؛ فالآخرة التي دل عليها الوحي هي خاصة ما يجحدونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص341–353.","url":""}]},{"id":"s7-247","number":247,"surah":7,"verses":[45],"verseLabel":"الأعراف: 45","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وهم بالآخرة كافرون﴾، وزاد في هود ضميرًا آخر فقال: ﴿وهم بالآخرة هم كافرون﴾؟","answer":"زاد ضمير الفصل في هود لأن السياق هناك أبلغ في توكيد اختصاصهم بالكفر بالآخرة وتكرار أوصافهم، أما الأعراف فاستغنى عنه بما في السياق.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-248","number":248,"surah":7,"verses":[46],"verseLabel":"الأعراف: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿وبينهما حجاب وعلى الأعراف رجال﴾؟","answer":"الحجاب يفصل بين الجنة والنار، وفوق أعاليه رجال يشرفون على الفريقين؛ فرتب المكان قبل ذكر أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص353–365.","url":""}]},{"id":"s7-249","number":249,"surah":7,"verses":[46],"verseLabel":"الأعراف: 46","question":"لماذا سُمي السور أو المكان ﴿الأعراف﴾؟","answer":"الأعراف جمع عُرف، وهو المكان المرتفع الظاهر من السور؛ سمي بذلك لعلوه وتمكن من عليه من معرفة الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص353–365.","url":""}]},{"id":"s7-250","number":250,"surah":7,"verses":[46],"verseLabel":"الأعراف: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿رجال يعرفون كلًّا بسيماهم﴾، دون أن يقال: يعرفون الفريقين؟","answer":"﴿كلًا﴾ تفيد معرفة كل فرد أو كل فريق بعلامته، وهي أعم وأوجز من قول «الفريقين».","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص353–365.","url":""}]},{"id":"s7-251","number":251,"surah":7,"verses":[46],"verseLabel":"الأعراف: 46","question":"لماذا نادوا أصحاب الجنة بالسلام مع أنهم ﴿لم يدخلوها وهم يطمعون﴾؟","answer":"سلامهم تحية لأهل الجنة وتفاؤل بمصيرهم، وقد عرفوا علاماتهم مع أنهم ما زالوا على الأعراف يطمعون في الدخول.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص353–365.","url":""}]},{"id":"s7-252","number":252,"surah":7,"verses":[46],"verseLabel":"الأعراف: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم يطمعون﴾ بالاسم المضارع؟","answer":"الجملة الاسمية تدل على ثبوت طمعهم واستمراره، والمضارع يستحضر تجدده وهم ينتظرون فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص353–365.","url":""}]},{"id":"s7-253","number":253,"surah":7,"verses":[47],"verseLabel":"الأعراف: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا صرفت أبصارهم تلقاء أصحاب النار﴾ بالبناء للمجهول؟","answer":"بُني للمجهول لأن نفوسهم لا تتجه اختيارًا إلى النار، بل تُحوّل أبصارهم إليها قهرًا للعبرة؛ وللاهتمام بالمشهد لا بالصارف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص365–374.","url":""}]},{"id":"s7-254","number":254,"surah":7,"verses":[47],"verseLabel":"الأعراف: 47","question":"لماذا اختير ﴿تلقاء﴾؟","answer":"﴿تلقاء﴾ تحدد الجهة المقابلة التي تقع فيها النار أمام أبصارهم، وتصور مواجهتهم المباشرة للمشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص365–374.","url":""}]},{"id":"s7-255","number":255,"surah":7,"verses":[47],"verseLabel":"الأعراف: 47","question":"ما دلالة قولهم: ﴿ربنا لا تجعلنا مع القوم الظالمين﴾ بدلًا من: من أهل النار؟","answer":"طلبوا ألا يُجعلوا في صحبة الظالمين لأن الصحبة تفيد المشاركة في حالهم ومصيرهم، وذكر الوصف يستعيذ من سبب النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص365–374.","url":""}]},{"id":"s7-256","number":256,"surah":7,"verses":[48],"verseLabel":"الأعراف: 48","question":"لماذا نادى أصحاب الأعراف رجالًا ﴿يعرفونهم بسيماهم﴾؟","answer":"نادوهم للتوبيخ والتقرير بعدما عرفوهم بعلامات الكبر والكفر، وإظهار انقلاب منزلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص374–385.","url":""}]},{"id":"s7-257","number":257,"surah":7,"verses":[48],"verseLabel":"الأعراف: 48","question":"ما سرّ التعبير بقوله تعالى: ﴿ما أغنى عنكم جمعكم وما كنتم تستكبرون﴾؟","answer":"الاستفهام التقريري يبين أن كثرة العدد أو المال واستكبارهم لم يدفع عنهم شيئًا من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص374–385.","url":""}]},{"id":"s7-258","number":258,"surah":7,"verses":[48],"verseLabel":"الأعراف: 48","question":"لماذا عبّر عن أتباعهم أو أموالهم بـ﴿جمعكم﴾؟","answer":"﴿جمعكم﴾ اسم جامع لما كانوا يجمعونه من مال ورجال وأتباع، وما اعتزوا به من قوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص374–385.","url":""}]},{"id":"s7-259","number":259,"surah":7,"verses":[49],"verseLabel":"الأعراف: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿أهؤلاء الذين أقسمتم لا ينالهم الله برحمة﴾؟","answer":"الاستفهام للتقرير والتوبيخ: هؤلاء الضعفاء الذين حلفتم ألا تصيبهم الرحمة قد أكرمهم الله، فظهر بطلان حكمكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص385–396.","url":""}]},{"id":"s7-260","number":260,"surah":7,"verses":[49],"verseLabel":"الأعراف: 49","question":"لماذا عُدّيت الرحمة بفعل ﴿ينالهم﴾؟","answer":"النيل يصور الرحمة كعطاء يصل إليهم ويصيبهم فعلًا، فيقابل إنكار المستكبرين لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص385–396.","url":""}]},{"id":"s7-261","number":261,"surah":7,"verses":[49],"verseLabel":"الأعراف: 49","question":"لماذا انتقل الخطاب فجأة إلى ﴿ادخلوا الجنة﴾؟","answer":"هو التفات إلى أصحاب الأعراف أو المؤمنين المبخوسين يأمرهم بالدخول، فيحسم الموقف بعد عرض قول المستكبرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص385–396.","url":""}]},{"id":"s7-262","number":262,"surah":7,"verses":[49],"verseLabel":"الأعراف: 49","question":"لماذا جمع نفي الخوف والحزن بعد الأمر بالدخول؟","answer":"نفي الخوف يؤمنهم من المستقبل، ونفي الحزن يزيل ألم الماضي؛ فتم لهم الأمن عند الدخول.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص385–396.","url":""}]},{"id":"s7-263","number":263,"surah":7,"verses":[50],"verseLabel":"الأعراف: 50","question":"ما سرّ طلب أصحاب النار بلفظ ﴿أفيضوا علينا من الماء﴾ بدلًا من: أعطونا ماء؟","answer":"الإفاضة إعطاء بكثرة وانصباب، فاختاروها لشدة عطشهم وحاجتهم إلى وفرة الماء لا مجرد قدر يسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص396–407.","url":""}]},{"id":"s7-264","number":264,"surah":7,"verses":[50],"verseLabel":"الأعراف: 50","question":"ما سرّ قولهم: ﴿أو مما رزقكم الله﴾ وإبهام سائر الرزق؟","answer":"أبهموا طمعًا في أي شيء من نعيم الجنة، فلا يهمهم نوع الرزق بعد الماء من شدة الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص396–407.","url":""}]},{"id":"s7-265","number":265,"surah":7,"verses":[50],"verseLabel":"الأعراف: 50","question":"لماذا جاء الرد: ﴿إن الله حرمهما على الكافرين﴾، فثنى الضمير؟","answer":"الضمير للماء وما رزق الله أهل الجنة؛ فثنى ليشمل المطلوبين معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص396–407.","url":""}]},{"id":"s7-266","number":266,"surah":7,"verses":[50],"verseLabel":"الأعراف: 50","question":"لماذا عُبّر عن المنع الأخروي بالتحريم؟","answer":"التحريم هنا المنع القطعي، لا حكم التكليف؛ أي قضى الله بحرمان الكافرين منهما في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص396–407.","url":""}]},{"id":"s7-267","number":267,"surah":7,"verses":[51],"verseLabel":"الأعراف: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿اتخذوا دينهم لهوًا ولعبًا﴾، وفي الأنعام: ﴿لعبًا ولهوًا﴾؟","answer":"في الأعراف قُدم اللهو لأن المقام في إعراضهم الذي ألهاهم عن الدين، وفي الأنعام قُدم اللعب لمناسبة سياق اتخاذ الدين عبثًا وسخرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص407–422.","url":""}]},{"id":"s7-268","number":268,"surah":7,"verses":[51],"verseLabel":"الأعراف: 51","question":"ما سرّ تقديم اللهو هنا وأُخر في الأنعام؟","answer":"تقديم كل منهما تابع لمحل العناية في السياق: الأعراف تبرز الانشغال والإلهاء بالدنيا، والأنعام تبرز العبث بالدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص407–422.","url":""}]},{"id":"s7-269","number":269,"surah":7,"verses":[51],"verseLabel":"الأعراف: 51","question":"ما المراد بقوله تعالى: ﴿فاليوم ننساهم كما نسوا لقاء يومهم هذا﴾، وهل النسيان هنا ذهول؟","answer":"النسيان من الله تركهم في العذاب وحرمانهم من الرحمة، لا ذهول العلم؛ جزاء إهمالهم الاستعداد للقاء يومهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص407–422.","url":""}]},{"id":"s7-270","number":270,"surah":7,"verses":[51],"verseLabel":"الأعراف: 51","question":"لماذا كرر ﴿يوم﴾ وأشار بـ﴿هذا﴾؟","answer":"كرر ﴿يوم﴾ لتعظيمه وتقرير اختصاص النسيان بلقائه، و﴿هذا﴾ تستحضر اليوم حاضرًا مشاهدًا بعدما أنكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص407–422.","url":""}]},{"id":"s7-271","number":271,"surah":7,"verses":[51],"verseLabel":"الأعراف: 51","question":"لماذا عطف ﴿وما كانوا بآياتنا يجحدون﴾ على نسيان اللقاء؟","answer":"جمعوا بين ترك الاستعداد للآخرة والجحود بالآيات؛ فالأول إعراض عملي والثاني إنكار اعتقادي، وكلاهما سبب الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص407–422.","url":""}]},{"id":"s7-272","number":272,"surah":7,"verses":[52],"verseLabel":"الأعراف: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد جئناهم بكتاب﴾، لا: أنزلنا عليهم؟","answer":"المجيء بالكتاب يصور بلوغه إليهم وقيام الحجة به بين أيديهم، ويشمل الإنزال والإبلاغ معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص422–432.","url":""}]},{"id":"s7-273","number":273,"surah":7,"verses":[52],"verseLabel":"الأعراف: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿فصلناه على علم﴾، وما دلالة ﴿على﴾؟","answer":"﴿على﴾ تفيد التمكن والاستناد: فُصل الكتاب تفصيلًا قائمًا على علم محيط بالمصالح والحقائق، لا عن جهل أو مصادفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص422–432.","url":""}]},{"id":"s7-274","number":274,"surah":7,"verses":[52],"verseLabel":"الأعراف: 52","question":"لماذا وصف الكتاب بأنه ﴿هدى ورحمة لقوم يؤمنون﴾؟","answer":"هو هدى بما يرشد إليه ورحمة بما يثمره اتباعه؛ وخص المؤمنين لأنهم المنتفعون بهذين الأثرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص422–432.","url":""}]},{"id":"s7-275","number":275,"surah":7,"verses":[53],"verseLabel":"الأعراف: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿هل ينظرون إلا تأويله﴾، واستعمل النظر بمعنى الانتظار؟","answer":"استعمل النظر بمعنى الانتظار لأنهم أعرضوا عن دلائل الكتاب ولم يبقوا ينتظرون إلا وقوع ما أخبر به.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص432–452.","url":""}]},{"id":"s7-276","number":276,"surah":7,"verses":[53],"verseLabel":"الأعراف: 53","question":"ما معنى مجيء ﴿تأويل﴾ الكتاب؟","answer":"تأويله تحقق مآله ووقوع ما وعد به من البعث والحساب والثواب والعقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص432–452.","url":""}]},{"id":"s7-277","number":277,"surah":7,"verses":[53],"verseLabel":"الأعراف: 53","question":"لماذا وُصفوا بأنهم ﴿نسوه من قبل﴾؟","answer":"أي تركوا العمل به والإيمان بمآله مع قيامه بينهم، فعوملوا معاملة من نسي شيئًا ولم يعتن به.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص432–452.","url":""}]},{"id":"s7-278","number":278,"surah":7,"verses":[53],"verseLabel":"الأعراف: 53","question":"ما مناسبة قولهم: ﴿قد جاءت رسل ربنا بالحق﴾ بعد مجيء التأويل؟","answer":"قالوه عند مشاهدة تحقق أخبار الرسل، إقرارًا متأخرًا بصدقهم لا ينفع بعد فوات زمن الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص432–452.","url":""}]},{"id":"s7-279","number":279,"surah":7,"verses":[53],"verseLabel":"الأعراف: 53","question":"لماذا طلبوا أولًا الشفعاء ثم طلبوا الرد إلى الدنيا؟","answer":"قدموا طلب الشفاعة رجاء دفع العذاب وهم في الآخرة، فلما يئسوا طلبوا الرجوع ليعملوا غير عملهم؛ فتدرجوا من الأقرب إلى المتعذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص432–452.","url":""}]},{"id":"s7-280","number":280,"surah":7,"verses":[53],"verseLabel":"الأعراف: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿قد خسروا أنفسهم وضل عنهم ما كانوا يفترون﴾؟","answer":"أضاعوا أنفسهم بإدخالها النار، وغابت عنهم الآلهة والأقوال التي اختلقوها فلم يبق لافترائهم أثر ينفعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص432–452.","url":""}]},{"id":"s7-281","number":281,"surah":7,"verses":[54],"verseLabel":"الأعراف: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿خلق السماوات والأرض في ستة أيام﴾ مع قدرته على ﴿كن فيكون﴾؟","answer":"خلقها في ستة أيام مع القدرة على التعجيل لإظهار التقدير والحكمة والترتيب، وتعليم الخلق التؤدة؛ لا لعجز أو حاجة إلى زمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص452–468.","url":""}]},{"id":"s7-282","number":282,"surah":7,"verses":[54],"verseLabel":"الأعراف: 54","question":"لماذا جُمعت السماوات وأُفردت الأرض؟","answer":"جُمعت السماوات لتعدد طبقاتها وعوالمها، وأفردت الأرض لأنها تبدو عالمًا واحدًا متصلًا للإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص452–468.","url":""}]},{"id":"s7-283","number":283,"surah":7,"verses":[54],"verseLabel":"الأعراف: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم استوى على العرش﴾، وما دلالة ﴿ثم﴾؟","answer":"الاستواء على العرش ثابت لله على الوجه اللائق به بلا تمثيل؛ و﴿ثم﴾ للترتيب في الخبر أو الرتبة وإظهار عظمة التدبير بعد الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص452–468.","url":""}]},{"id":"s7-284","number":284,"surah":7,"verses":[54],"verseLabel":"الأعراف: 54","question":"لماذا صُور الليل بأنه ﴿يغشي﴾ النهار؟","answer":"شُبه الليل بغطاء يلبس النهار ويستره بظلمته، فصوّر التعاقب إحاطةً وتغطية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص452–468.","url":""}]},{"id":"s7-285","number":285,"surah":7,"verses":[54],"verseLabel":"الأعراف: 54","question":"ما سرّ التعبير في قوله تعالى عن النهار: ﴿يطلبه حثيثًا﴾؟","answer":"شُبه تعاقب الليل والنهار بطالب يلاحق مطلوبه بسرعة؛ و﴿حثيثًا﴾ تؤكد دوام الحركة وسرعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص452–468.","url":""}]},{"id":"s7-286","number":286,"surah":7,"verses":[54],"verseLabel":"الأعراف: 54","question":"لماذا عطف الشمس والقمر والنجوم منصوبة أو مرفوعة بحسب القراءة؟","answer":"في النصب عطف على السماوات أو مفعول لفعل مقدر، وفي الرفع ابتداء أو عطف على موضع الفاعل؛ وتتفق القراءتان في انتظام الأجرام ضمن دلائل التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص452–468.","url":""}]},{"id":"s7-287","number":287,"surah":7,"verses":[54],"verseLabel":"الأعراف: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿مسخرات بأمره﴾؟","answer":"الحال تبين أنها مذللة منقادة لتدبيره لا تخرج عن نظامه، و﴿بأمره﴾ يقصر تسخيرها على إرادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص452–468.","url":""}]},{"id":"s7-288","number":288,"surah":7,"verses":[54],"verseLabel":"الأعراف: 54","question":"لماذا فُصل بين ﴿الخلق﴾ و﴿الأمر﴾: ﴿ألا له الخلق والأمر﴾؟","answer":"الخلق له وحده إيجادًا، والأمر له وحده حكمًا وتدبيرًا وتشريعًا؛ فجمع ملك الأعيان وملك التصرف فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص452–468.","url":""}]},{"id":"s7-289","number":289,"surah":7,"verses":[54],"verseLabel":"الأعراف: 54","question":"لماذا خُتمت بـ﴿تبارك الله رب العالمين﴾؟","answer":"جاء التذييل بعد دلائل الخلق والتسخير إعلانًا لكثرة خير الله وعظمته واستحقاقه الربوبية للعالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص452–468.","url":""}]},{"id":"s7-290","number":290,"surah":7,"verses":[55],"verseLabel":"الأعراف: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿ادعوا ربكم﴾، واختار اسم الرب؟","answer":"اختير الرب لاستدعاء معنى التربية والإنعام والقرب من عباده، وهو أنسب بحال السائل المفتقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص468–478.","url":""}]},{"id":"s7-291","number":291,"surah":7,"verses":[55],"verseLabel":"الأعراف: 55","question":"لماذا جمع بين ﴿تضرعًا وخفية﴾؟","answer":"التضرع ذل القلب وخضوعه، والخفية إسرار الصوت وإبعاده عن الرياء؛ فجمع حال الباطن وأدب الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص468–478.","url":""}]},{"id":"s7-292","number":292,"surah":7,"verses":[55],"verseLabel":"الأعراف: 55","question":"ما سرّ تقديم العلانية القلبية في التضرع على الخفية؟","answer":"قُدم التضرع لأنه روح الدعاء وأصله القلبي، ثم ذُكرت الخفية هيئةً لصوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص468–478.","url":""}]},{"id":"s7-293","number":293,"surah":7,"verses":[55],"verseLabel":"الأعراف: 55","question":"لماذا خُتمت بـ﴿إنه لا يحب المعتدين﴾، وما الاعتداء في الدعاء؟","answer":"الاعتداء تجاوز حد الدعاء: كطلب المحرم أو المحال أو رفع الصوت والصياح والتكلف؛ ونفي المحبة يتضمن الزجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص468–478.","url":""}]},{"id":"s7-294","number":294,"surah":7,"verses":[55,205],"verseLabel":"الأعراف: 55، 205","question":"ما الفرق بين قوله في الدعاء: ﴿تضرعًا وخُفية﴾، وقوله في الذكر آخر الأعراف: ﴿تضرعًا وخِيفة﴾؟","answer":"في الدعاء قُصد أدب إخفاء الصوت فقيل ﴿خُفية﴾، أما الذكر في النفس فخفاؤه حاصل، فناسب ذكر خوف القلب ﴿خِيفة﴾.","sources":[{"label":"فاضل السامرائي: الخوف في آيتي الأعراف.","url":""}]},{"id":"s7-295","number":295,"surah":7,"verses":[56],"verseLabel":"الأعراف: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تفسدوا في الأرض بعد إصلاحها﴾، وأسند الإصلاح من غير فاعل؟","answer":"بُني ﴿إصلاحها﴾ من غير فاعل ليعم ما أصلحه الله بالخلق والشرع وما أصلحه المصلحون؛ فكل إصلاح يحرم إفساده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص478–487.","url":""}]},{"id":"s7-296","number":296,"surah":7,"verses":[56],"verseLabel":"الأعراف: 56","question":"لماذا قُيد النهي بقوله: ﴿بعد إصلاحها﴾؟","answer":"القيد يشدد القبح؛ فالإفساد بعد قيام الصلاح ونظامه نقض للنعمة وتخريب لما استقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص478–487.","url":""}]},{"id":"s7-297","number":297,"surah":7,"verses":[56],"verseLabel":"الأعراف: 56","question":"لماذا جمع في الدعاء بين ﴿خوفًا وطمعًا﴾؟","answer":"الخوف يمنع الأمن من مكر الله، والطمع يمنع اليأس من رحمته؛ واعتدال الدعاء بهما يجمع الهيبة والرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص478–487.","url":""}]},{"id":"s7-298","number":298,"surah":7,"verses":[56],"verseLabel":"الأعراف: 56","question":"ما سرّ تقديم الخوف على الطمع؟","answer":"قُدم الخوف لأن السياق بدأ بالنهي عن الإفساد، ولأن دفع الضرر والتوبة من الذنب يسبقان طلب الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص478–487.","url":""}]},{"id":"s7-299","number":299,"surah":7,"verses":[56],"verseLabel":"الأعراف: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿إن رحمت الله قريب﴾، فوصف الرحمة المؤنثة بـ﴿قريب﴾؟","answer":"ذُكّر ﴿قريب﴾ على تأويل الرحمة بالرحم أو الإحسان أو الشيء القريب، وقيل لأن فعيلًا بمعنى فاعل أو مفعول يستوي فيه التذكير والتأنيث؛ وهذه وجوه عربية صحيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص478–487؛ باحث، تفريغ د. فاضل السامرائي: «إن رحمت الله قريب من المحسنين».","url":""}]},{"id":"s7-300","number":300,"surah":7,"verses":[56],"verseLabel":"الأعراف: 56","question":"لماذا خُص المحسنون بقرب الرحمة؟","answer":"خُصوا لأن الإحسان امتثال الأمر وترك الإفساد والدعاء خوفًا وطمعًا؛ فمن حقق سببه كان أحق بقرب الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص478–487.","url":""}]},{"id":"s7-301","number":301,"surah":7,"verses":[57],"verseLabel":"الأعراف: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿يرسل الرياح بشرًا بين يدي رحمته﴾؟","answer":"جعل إرسال الرياح المتنوعة المتتابعة بشارةً تتقدم نزول المطر؛ فـ﴿بين يدي رحمته﴾ تمثيل لسبقها الرحمة، والرحمة هنا المطر وما ينشأ عنه من حياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص487–508.","url":""}]},{"id":"s7-302","number":302,"surah":7,"verses":[57],"verseLabel":"الأعراف: 57","question":"لماذا جُمعت ﴿الرياح﴾ هنا، وتأتي ﴿الريح﴾ مفردة في مواضع العذاب؟","answer":"جُمعت الرياح في مقام الرحمة لاختلاف جهاتها ومنافعها وتعاونها في سوق السحاب، وجاءت الريح مفردة في كثير من مواضع العذاب لأنها قوة واحدة مستمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص487–508.","url":""}]},{"id":"s7-303","number":303,"surah":7,"verses":[57],"verseLabel":"الأعراف: 57","question":"لماذا سُمي المطر ﴿رحمته﴾؟","answer":"سُمّي المطر رحمةً لأنه سبب الرحمة؛ فبه تحيا الأرض ويخرج الرزق، فأطلق اسم الأثر على سببه بيانًا لعظم النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص487–508.","url":""}]},{"id":"s7-304","number":304,"surah":7,"verses":[57],"verseLabel":"الأعراف: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا أقلت سحابًا ثقالًا﴾، فأسند الحمل إلى الرياح؟","answer":"الإقلال حمل الشيء ورفعه؛ فالرياح تحمل السحاب وتسوقه، فأسند إليها الحمل لأنها السبب الظاهر الذي سخّره الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص487–508.","url":""}]},{"id":"s7-305","number":305,"surah":7,"verses":[57],"verseLabel":"الأعراف: 57","question":"لماذا جُمع ﴿ثقالًا﴾ مع إفراد ﴿سحابًا﴾؟","answer":"﴿سحاب﴾ اسم جنس جمعي يدل على قطع السحاب، فروعِي معناه الجمعي في وصفه بـ﴿ثقالًا﴾؛ وثقلها بما تحمله من الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص487–508.","url":""}]},{"id":"s7-306","number":306,"surah":7,"verses":[57],"verseLabel":"الأعراف: 57","question":"لماذا انتقل من الغيبة إلى التكلم: ﴿سقناه لبلد ميت فأنزلنا﴾؟","answer":"الانتقال إلى ضمير العظمة يلفت إلى مباشرة القدرة الإلهية للأفعال العظيمة: سوق السحاب وإنزال الماء وإخراج الثمرات.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص487–508.","url":""}]},{"id":"s7-307","number":307,"surah":7,"verses":[57],"verseLabel":"الأعراف: 57","question":"لماذا وُصف البلد بـ﴿ميت﴾، لا: ميتة؟","answer":"جاء الوصف مذكرًا موافقةً للفظ ﴿بلد﴾ المذكر؛ والمراد أرض بلد ميتة بالنبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص487–508.","url":""}]},{"id":"s7-308","number":308,"surah":7,"verses":[57],"verseLabel":"الأعراف: 57","question":"لماذا شُبه إخراج الموتى بإخراج الثمرات: ﴿كذلك نخرج الموتى﴾؟","answer":"إحياء الأرض بالماء مثال محسوس لإحياء الأجساد؛ فالذي أخرج النبات من الأرض الميتة قادر على إخراج الموتى.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص487–508.","url":""}]},{"id":"s7-309","number":309,"surah":7,"verses":[57],"verseLabel":"الأعراف: 57","question":"ما سرّ التعبير في قوله تعالى في الأعراف والروم: ﴿يرسل الرياح﴾ بالمضارع، وفي الفرقان وفاطر: ﴿أرسل الرياح﴾ بالماضي؟","answer":"جاء المضارع في الأعراف لمناسبة الخوف والطمع المتعلقين بالمستقبل، وفي الروم لمناسبة ﴿أن يرسل الرياح﴾؛ وجاء الماضي في فاطر لمناسبة أوصاف المطلع الدالة على المضي.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-310","number":310,"surah":7,"verses":[58],"verseLabel":"الأعراف: 58","question":"ما سرّ التعبير في قوله تعالى: ﴿والبلد الطيب يخرج نباته بإذن ربه﴾، فأضاف الرب إلى البلد؟","answer":"إضافة الرب إلى البلد تستحضر التربية والتدبير؛ فنبات الأرض الطيبة لا يخرج مستقلًا، بل بتيسير ربها وإذنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص508–528.","url":""}]},{"id":"s7-311","number":311,"surah":7,"verses":[58],"verseLabel":"الأعراف: 58","question":"لماذا أسند إخراج النبات إلى البلد؟","answer":"أُسند الإخراج إلى البلد مجازًا لأنه محله وسببه القريب، ثم قُيّد بـ﴿بإذن ربه﴾ لرد الأمر إلى مسببه الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص508–528.","url":""}]},{"id":"s7-312","number":312,"surah":7,"verses":[58],"verseLabel":"الأعراف: 58","question":"ما سرّ التعبير في قوله تعالى في البلد الخبيث: ﴿لا يخرج إلا نكدًا﴾، وحذف نباته؟","answer":"حُذف ﴿نباته﴾ لدلالة ما قبله عليه، ولتتجه العناية إلى هيئة الخروج: فلا يصدر من الأرض الخبيثة إلا خارج نكد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص508–528.","url":""}]},{"id":"s7-313","number":313,"surah":7,"verses":[58],"verseLabel":"الأعراف: 58","question":"لماذا اختير ﴿نكدًا﴾، لا: قليلًا؟","answer":"النكد ليس مجرد القلة، بل ما يخرج بعسر ويكون قليل الخير والمنفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص508–528.","url":""}]},{"id":"s7-314","number":314,"surah":7,"verses":[58],"verseLabel":"الأعراف: 58","question":"لماذا صار اختلاف الأرض مثلًا لاختلاف القلوب؟","answer":"الأرض الطيبة تقبل الماء فتخرج النافع، والخبيثة لا تخرج إلا نكدًا؛ وكذلك القلوب: منها ما يقبل الوحي فيثمر، ومنها ما لا ينتفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص508–528.","url":""}]},{"id":"s7-315","number":315,"surah":7,"verses":[58],"verseLabel":"الأعراف: 58","question":"لماذا خُتمت بـ﴿كذلك نصرف الآيات لقوم يشكرون﴾؟","answer":"خُتمت بالشكر لأن تصريف الدلائل وإنزال المطر وإخراج النبات نعم، ولا ينتفع بآياتها حقًا إلا من عرف المنعم وشكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص508–528.","url":""}]},{"id":"s7-316","number":316,"surah":7,"verses":[59],"verseLabel":"الأعراف: 59","question":"لماذا افتتحت قصص الرسل بنوح؟","answer":"افتتحت القصص بنوح لأنه أول رسول إلى قوم ظهر فيهم الشرك، ومن قصته يبدأ تاريخ مواجهة الرسل للتكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص528–539.","url":""}]},{"id":"s7-317","number":317,"surah":7,"verses":[59],"verseLabel":"الأعراف: 59","question":"ما سرّ نداء نوح قومه بقوله: ﴿يا قوم اعبدوا الله﴾؟","answer":"في ﴿يا قوم﴾ استمالة بنداء القرابة والقرب، وإظهار لشفقة الرسول على قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص528–539.","url":""}]},{"id":"s7-318","number":318,"surah":7,"verses":[59],"verseLabel":"الأعراف: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿ما لكم من إله غيره﴾، دون أن يقال: لا إله إلا هو؟","answer":"ينفي الأسلوب أن يكون لهم أي إله مستحق للعبادة غير الله، و﴿من﴾ تؤكد استغراق النفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص528–539.","url":""}]},{"id":"s7-319","number":319,"surah":7,"verses":[59],"verseLabel":"الأعراف: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿إني أخاف عليكم﴾، دون أن يقال: أخوفكم؟","answer":"﴿أخاف عليكم﴾ تظهر شفقته وأن الخوف لأجلهم من العذاب؛ أما «أخوفكم» فمحورها إيقاع الخوف بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص528–539.","url":""}]},{"id":"s7-320","number":320,"surah":7,"verses":[59],"verseLabel":"الأعراف: 59","question":"لماذا وصف اليوم نفسه بالعظمة: ﴿عذاب يوم عظيم﴾؟","answer":"وُصف اليوم بالعظمة لعظم ما يقع فيه من أهوال وعذاب، فتعظيم الزمن تعظيم لما اشتمل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص528–539.","url":""}]},{"id":"s7-321","number":321,"surah":7,"verses":[59],"verseLabel":"الأعراف: 59","question":"لماذا بدأت قصة نوح في الأعراف بـ﴿لقد أرسلنا نوحًا﴾ بلا واو، وفي هود والمؤمنون بـ﴿ولقد أرسلنا نوحًا﴾؟","answer":"بدأت القصة بلا واو لأنها أول قصص الرسل في السورة، فهي استئناف لا عطف؛ أما في هود والمؤمنون فجاءت معطوفة على كلام سابق.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-322","number":322,"surah":7,"verses":[60],"verseLabel":"الأعراف: 60","question":"لماذا كان جواب الملأ: ﴿إنا لنراك في ضلال مبين﴾ بدل مناقشة دعوته؟","answer":"عدل الملأ عن مناقشة التوحيد إلى اتهام الرسول لعجزهم عن حجة على شركهم؛ فكان قولهم تشنيعًا لا جوابًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص539–547.","url":""}]},{"id":"s7-323","number":323,"surah":7,"verses":[60],"verseLabel":"الأعراف: 60","question":"لماذا وصف رؤيتهم بالضلال بـ﴿لنراك﴾؟","answer":"﴿لنراك﴾ يصور دعواهم كأنها أمر مشاهد، وزادوا اللام لتوكيد اتهامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص539–547.","url":""}]},{"id":"s7-324","number":324,"surah":7,"verses":[60],"verseLabel":"الأعراف: 60","question":"ما سرّ تعبيرهم بقولهم: ﴿في ضلال﴾، فجعلوه محيطًا به؟","answer":"صوّروا الضلال ظرفًا يحيط به ويتمكن منه، مبالغةً في اتهامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص539–547.","url":""}]},{"id":"s7-325","number":325,"surah":7,"verses":[61],"verseLabel":"الأعراف: 61","question":"لماذا أجاب نوح: ﴿ليس بي ضلالة﴾، ولم يقل: لست ضالًا؟","answer":"نفي أن تكون به ﴿ضلالة﴾ ينفي أن تلابسه أدنى خصلة من الضلال، وهو أبلغ من «لست ضالًا».","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص547–554.","url":""}]},{"id":"s7-326","number":326,"surah":7,"verses":[61],"verseLabel":"الأعراف: 61","question":"لماذا أفرد ﴿ضلالة﴾ مع قولهم ﴿في ضلال﴾؟","answer":"أفرد ﴿ضلالة﴾ لينفي عنه فردًا واحدًا من جنس الضلال، فضلًا عن الغرق فيه كما زعموا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص547–554.","url":""}]},{"id":"s7-327","number":327,"surah":7,"verses":[61],"verseLabel":"الأعراف: 61","question":"لماذا استدرك: ﴿ولكني رسول من رب العالمين﴾؟","answer":"الاستدراك يزيل تهمتهم ثم يثبت الحقيقة المقابلة: ليس به ضلالة، وإنما هو رسول من رب العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص547–554.","url":""}]},{"id":"s7-328","number":328,"surah":7,"verses":[62],"verseLabel":"الأعراف: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿أبلغكم رسالات ربي﴾ بالجمع؟","answer":"جُمعت ﴿رسالات﴾ لتعدد ما يبلغه من أوامر ونواه ومواعظ وأخبار، أو لأن أجزاء الرسالة المتتابعة بمنزلة رسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص554–565.","url":""}]},{"id":"s7-329","number":329,"surah":7,"verses":[62],"verseLabel":"الأعراف: 62","question":"لماذا اختير المضارع ﴿أبلغكم وأنصح لكم﴾؟","answer":"المضارع يدل على تجدد التبليغ والنصح واستمرارهما، لا على فعل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص554–565.","url":""}]},{"id":"s7-330","number":330,"surah":7,"verses":[62],"verseLabel":"الأعراف: 62","question":"لماذا عُدي النصح باللام: ﴿أنصح لكم﴾؟","answer":"عُدّي النصح باللام لأنه إرادة الخير للمنصوح وتوجيهه إلى ما ينفعه؛ فاللام تبرز منفعة نصحه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص554–565.","url":""}]},{"id":"s7-331","number":331,"surah":7,"verses":[62],"verseLabel":"الأعراف: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿وأعلم من الله ما لا تعلمون﴾؟","answer":"أي أعلم من وحي الله وأحكامه وعاقبة التكذيب ما لا تعلمونه؛ فإنذاره مبني على علم من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص554–565.","url":""}]},{"id":"s7-332","number":332,"surah":7,"verses":[63],"verseLabel":"الأعراف: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿أوعجبتم أن جاءكم ذكر من ربكم﴾ في صورة إنكار؟","answer":"الاستفهام إنكاري: لا موجب لتعجبهم من الوحي، فإرسال بشر منهم تقتضيه الحكمة ولا يصح ذريعة للتكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص565–577.","url":""}]},{"id":"s7-333","number":333,"surah":7,"verses":[63],"verseLabel":"الأعراف: 63","question":"لماذا سُمي الوحي ﴿ذكرًا﴾؟","answer":"سُمّي الوحي ﴿ذكرًا﴾ لأنه يذكّر الغافل ويعظه، ويمنح متبعه الذكر والشرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص565–577.","url":""}]},{"id":"s7-334","number":334,"surah":7,"verses":[63],"verseLabel":"الأعراف: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿على رجل منكم﴾، لا: إلى رجل؟","answer":"﴿على﴾ تلائم نزول الوحي واستقراره على الرسول وتحمّله أمانته، لا مجرد انتهائه إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص565–577.","url":""}]},{"id":"s7-335","number":335,"surah":7,"verses":[63],"verseLabel":"الأعراف: 63","question":"لماذا ذكر بشريته وقربه: ﴿رجل منكم﴾؟","answer":"﴿رجل منكم﴾ يرفع الاستغراب؛ فهو بشر يعرفون نسبه ولسانه وصدقه، فيسهل تلقي البيان عنه وتقوم الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص565–577.","url":""}]},{"id":"s7-336","number":336,"surah":7,"verses":[63],"verseLabel":"الأعراف: 63","question":"لماذا ترتبت الغايات: ﴿لينذركم ولتتقوا ولعلكم ترحمون﴾؟","answer":"الترتيب سببي: جاء الذكر للإنذار، والإنذار يحمل على التقوى، والتقوى سبب يرجى به نيل الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص565–577.","url":""}]},{"id":"s7-337","number":337,"surah":7,"verses":[64],"verseLabel":"الأعراف: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿فكذبوه فأنجيناه﴾ بفاءين متتابعتين؟","answer":"الفاء الأولى تفيد تعقيب التكذيب للدعوة، والثانية تصور سرعة ترتب النجاة والهلاك عليه حين جاء أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص577–590.","url":""}]},{"id":"s7-338","number":338,"surah":7,"verses":[64],"verseLabel":"الأعراف: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين معه في الفلك﴾، دون أن يقال: ومن آمن معه؟","answer":"جمعت العبارة صحبتهم لنوح ووجودهم في وسيلة النجاة؛ فالعبرة بمن صدق واتبع وركب الفلك معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص577–590.","url":""}]},{"id":"s7-339","number":339,"surah":7,"verses":[64],"verseLabel":"الأعراف: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿وأغرقنا الذين كذبوا بآياتنا﴾، فأظهر الصلة بدل الضمير؟","answer":"أظهر ﴿الذين كذبوا بآياتنا﴾ بدل الضمير لتسجيل سبب الإغراق عليهم: تكذيبهم بآيات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص577–590.","url":""}]},{"id":"s7-340","number":340,"surah":7,"verses":[64],"verseLabel":"الأعراف: 64","question":"لماذا خُتمت بـ﴿إنهم كانوا قومًا عمين﴾؟","answer":"الخاتمة تعلل التكذيب والإغراق بعمى البصيرة المتأصل؛ و﴿كانوا﴾ تدل على رسوخ الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص577–590.","url":""}]},{"id":"s7-341","number":341,"surah":7,"verses":[64],"verseLabel":"الأعراف: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿عمين﴾ بصيغة النسب، لا: عميان؟","answer":"﴿عمين﴾ وصف لعمى القلب والبصيرة، أما العميان فالأصل فيه العمى الحسي؛ والمقام لعمى الضلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص577–590.","url":""}]},{"id":"s7-342","number":342,"surah":7,"verses":[64],"verseLabel":"الأعراف: 64","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿فأنجيناه والذين معه﴾، وفي يونس: ﴿فنجيناه ومن معه﴾؛ فاختار «أنجينا/الذين» هنا و«نجّينا/من» هناك؟","answer":"كلتا الصيغتين للتعدية، لكن التشديد في ﴿نجّيناه﴾ للمبالغة، فناسبه ﴿من معه﴾ الأعم، وناسب ﴿أنجيناه﴾ هنا ﴿الذين معه﴾.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-343","number":343,"surah":7,"verses":[65],"verseLabel":"الأعراف: 65","question":"ما سرّ التعبير في قوله تعالى: ﴿وإلى عاد أخاهم هودًا﴾، فجعل هودًا أخًا لهم؟","answer":"الأخوة أخوة نسب وقوم، وفيها استمالة وإظهار للنصح والمودة؛ وليست أخوة دين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص590–595.","url":""}]},{"id":"s7-344","number":344,"surah":7,"verses":[65],"verseLabel":"الأعراف: 65","question":"لماذا حُذف فعل الإرسال قبل ﴿إلى عاد﴾؟","answer":"حُذف ﴿أرسلنا﴾ اعتمادًا على قصة نوح، والتقدير: وأرسلنا إلى عاد أخاهم هودًا؛ فالإيجاز يربط القصص.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص590–595.","url":""}]},{"id":"s7-345","number":345,"surah":7,"verses":[65],"verseLabel":"الأعراف: 65","question":"لماذا خُتمت دعوته بـ﴿أفلا تتقون﴾، بينما قال نوح: ﴿إني أخاف عليكم﴾؟","answer":"انتقل خطاب هود إلى التحضيض على التقوى بعد بيان عاقبة قوم نوح، فصار في مصيرهم زاجر يغني عن بسط الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص590–595.","url":""}]},{"id":"s7-346","number":346,"surah":7,"verses":[66],"verseLabel":"الأعراف: 66","question":"لماذا وصف المتكلمون بأنهم ﴿الملأ الذين كفروا من قومه﴾؟","answer":"قيّد الملأ بالذين كفروا لأن في قومه غيرهم، وللتنبيه إلى أن الكفر حملهم على رد الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص595–601.","url":""}]},{"id":"s7-347","number":347,"surah":7,"verses":[66],"verseLabel":"الأعراف: 66","question":"ما سرّ تعبير قوم هود عنه بأنه ﴿في سفاهة﴾، وتعبير قوم نوح عنه بأنه ﴿في ضلال﴾؟","answer":"اتهم قوم نوح رسولهم بالضلال، أي مفارقة الطريق المألوف، واتهم عاد هودًا بالسفاهة لأنهم عدّوا ترك آلهة الآباء خفة عقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص595–601.","url":""}]},{"id":"s7-348","number":348,"surah":7,"verses":[66],"verseLabel":"الأعراف: 66","question":"لماذا أكدوا مرتين: ﴿إنا لنراك... وإنا لنظنك﴾؟","answer":"كرروا ﴿إنا﴾ واللام لتوكيد كل تهمة على حدة: السفاهة والكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص595–601.","url":""}]},{"id":"s7-349","number":349,"surah":7,"verses":[66],"verseLabel":"الأعراف: 66","question":"ما سرّ تعبيرهم في الكذب بـ﴿لنظنك من الكاذبين﴾، مع جزمهم بالسفاهة؟","answer":"زعموا السفاهة كأنها مشاهدة بـ﴿لنراك﴾، أما الكذب فمتعلق بالخبر والنية فلا يدرك بالمشاهدة، فلم يملكوا إلا الظن.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص595–601.","url":""}]},{"id":"s7-350","number":350,"surah":7,"verses":[66],"verseLabel":"الأعراف: 66","question":"لماذا جاء جواب الملأ في الأعراف: ﴿قال الملأ﴾ بلا فاء، وفي هود والمؤمنون: ﴿فقال الملأ﴾؟","answer":"جاء ﴿قال الملأ﴾ بلا فاء لأن قولهم هنا ليس جوابًا صالحًا للدعوة بل اتهام؛ وجيء بالفاء في المواضع الأخرى حيث ساقوا ما زعموه جوابًا.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-351","number":351,"surah":7,"verses":[67],"verseLabel":"الأعراف: 67","question":"لماذا أجاب هود: ﴿ليس بي سفاهة﴾ على نسق جواب نوح؟","answer":"قابل هود تهمتهم بنفي هادئ مطابق ﴿ليس بي سفاهة﴾، ثم أثبت رسالته؛ وفي تكرر النسق بيان وحدة دعوة الرسل وحسن ردهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص601–605.","url":""}]},{"id":"s7-352","number":352,"surah":7,"verses":[67],"verseLabel":"الأعراف: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿رسول من رب العالمين﴾ كما قال نوح؟","answer":"التعبير نفسه يقرر وحدة مصدر الرسالات؛ فهود ونوح لا يدعوان لأنفسهما، وإنما يبلغ كل منهما عن رب العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص601–605.","url":""}]},{"id":"s7-353","number":353,"surah":7,"verses":[68],"verseLabel":"الأعراف: 68","question":"ما سرّ تعبير هود بقوله: ﴿أبلغكم رسالات ربي﴾ بالمضارع والجمع؟","answer":"المضارع لاستمرار التبليغ وتجدده، والجمع لتعدد ما يبلغه من أوامر ونواه ووعد ووعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص605–612.","url":""}]},{"id":"s7-354","number":354,"surah":7,"verses":[68],"verseLabel":"الأعراف: 68","question":"ما سرّ تعبير هود بقوله: ﴿وأنا لكم ناصح أمين﴾، وتعبير نوح بقوله: ﴿وأنصح لكم﴾؟","answer":"عبّر هود بالجملة الاسمية ﴿وأنا لكم ناصح أمين﴾ لإثبات رسوخ النصح والأمانة، وهو أنسب للرد على اتهامه بالكذب؛ أما نوح فذكر فعل النصح المتجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص605–612.","url":""}]},{"id":"s7-355","number":355,"surah":7,"verses":[68],"verseLabel":"الأعراف: 68","question":"لماذا جمع هود بين ﴿ناصح﴾ و﴿أمين﴾؟","answer":"﴿ناصح﴾ يثبت إرادة الخير لهم، و﴿أمين﴾ يثبت صدقه في نقل رسالة ربه؛ فانتفى الغش في القصد والخيانة في البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص605–612.","url":""}]},{"id":"s7-356","number":356,"surah":7,"verses":[69],"verseLabel":"الأعراف: 69","question":"لماذا تكرر إنكار العجب نفسه في قصة هود؟","answer":"تكرر الإنكار لأن عادًا تعجبوا من الرسالة كما تعجب قوم نوح؛ فوحدة الشبهة اقتضت وحدة نقضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص612–627.","url":""}]},{"id":"s7-357","number":357,"surah":7,"verses":[69],"verseLabel":"الأعراف: 69","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿لينذركم﴾ وحذف ﴿ولتتقوا ولعلكم ترحمون﴾؟","answer":"اقتصر هنا على غاية الإنذار لأن المقام مع عاد اشتد فيه التهديد والتذكير بمصير قوم نوح، فناسب الإيجاز والتركيز على الزجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص612–627.","url":""}]},{"id":"s7-358","number":358,"surah":7,"verses":[69],"verseLabel":"الأعراف: 69","question":"لماذا ذكّر عادًا بأنهم ﴿خلفاء من بعد قوم نوح﴾؟","answer":"ذكّرهم أنهم خلفاء بعد قوم نوح ليجمع لهم النعمة والعبرة: أورثهم الله الأرض بعد الهالكين، فلا يسلكوا طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص612–627.","url":""}]},{"id":"s7-359","number":359,"surah":7,"verses":[69],"verseLabel":"الأعراف: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿وزادكم في الخلق بسطة﴾؟","answer":"البسطة هي الزيادة في عظم الأجسام والقوة والقدرة؛ فذكّرهم بما خصهم الله به مما يقتضي الشكر لا الاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص612–627.","url":""}]},{"id":"s7-360","number":360,"surah":7,"verses":[69],"verseLabel":"الأعراف: 69","question":"لماذا كرر الأمر بالذكر: ﴿فاذكروا آلاء الله لعلكم تفلحون﴾؟","answer":"الأمر الثاني متعلق بنعم مخصوصة ذُكرت بعد الأول: الاستخلاف والبسطة؛ فتجدد الأمر بالذكر لتتجدد ملاحظة الآلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص612–627.","url":""}]},{"id":"s7-361","number":361,"surah":7,"verses":[70],"verseLabel":"الأعراف: 70","question":"ما سرّ تعبيرهم بقوله: ﴿أجئتنا لنعبد الله وحده﴾، فجعلوا التوحيد مستنكرًا؟","answer":"صاغوا التوحيد في صورة أمر مستنكر لأن ألفتهم للشرك قلبت موازينهم، حتى صار إفراد الخالق بالعبادة موضع تعجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص627–638.","url":""}]},{"id":"s7-362","number":362,"surah":7,"verses":[70],"verseLabel":"الأعراف: 70","question":"ما سرّ إسناد العبادة إلى الآباء في قولهم: ﴿ونذر ما كان يعبد آباؤنا﴾؟","answer":"احتجوا بعبادة الآباء بدل الحجة، تعظيمًا للموروث وتقليدًا له؛ فكشف التعبير أن مستندهم عادة السابقين لا سلطان من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص627–638.","url":""}]},{"id":"s7-363","number":363,"surah":7,"verses":[70],"verseLabel":"الأعراف: 70","question":"ما سرّ طلبهم ﴿فأتنا بما تعدنا﴾، دون: بما تتوعدنا؟","answer":"سموا العذاب ﴿ما تعدنا﴾ تهكمًا وتحديًا؛ فالوعيد وعد من جهة الإخبار بأمر مستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص627–638.","url":""}]},{"id":"s7-364","number":364,"surah":7,"verses":[70],"verseLabel":"الأعراف: 70","question":"لماذا قيدوا الطلب بـ﴿إن كنت من الصادقين﴾؟","answer":"علقوا طلب العذاب على صدقه استهزاءً وتكذيبًا: إن كنت صادقًا فيما تخبر به فأنزله بنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص627–638.","url":""}]},{"id":"s7-365","number":365,"surah":7,"verses":[71],"verseLabel":"الأعراف: 71","question":"ما سرّ تعبير هود بالماضي في قوله: ﴿قد وقع عليكم من ربكم رجس وغضب﴾؟","answer":"الماضي في ﴿وقع﴾ لتحقق العذاب ووجوبه وقربه حتى صُوّر كأنه وقع؛ فوعيد الله لا مرد له.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص638–650.","url":""}]},{"id":"s7-366","number":366,"surah":7,"verses":[71],"verseLabel":"الأعراف: 71","question":"لماذا جمع بين ﴿رجس وغضب﴾؟","answer":"الرجس هو العذاب أو السخط الملازم للخبث، والغضب سبب الانتقام والدال على شدة المؤاخذة؛ فجمعهما لإحاطة الوعيد بسببه وأثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص638–650.","url":""}]},{"id":"s7-367","number":367,"surah":7,"verses":[71],"verseLabel":"الأعراف: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿أتجادلونني في أسماء سميتموها﴾، مع أن الجدال في معبودات؟","answer":"سمّاها أسماء لأنها لا تملك من حقيقة الألوهية إلا الألفاظ التي أطلقوها عليها؛ فالجدال في مسميات جوفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص638–650.","url":""}]},{"id":"s7-368","number":368,"surah":7,"verses":[71],"verseLabel":"الأعراف: 71","question":"لماذا كرر مادة الاسم: ﴿أسماء سميتموها﴾؟","answer":"تكرار مادة الاسم يفضح منشأها البشري: هي أسماء اخترعتموها أنتم وآباؤكم، ولم يجعل الله لمسمياتها ألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص638–650.","url":""}]},{"id":"s7-369","number":369,"surah":7,"verses":[71],"verseLabel":"الأعراف: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿ما نزل الله بها من سلطان﴾؟","answer":"أي لم ينزل الله حجة تثبت عبادتها، و﴿من﴾ تستغرق أدنى سلطان؛ فانتفاء أقل برهان يبطل جدالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص638–650.","url":""}]},{"id":"s7-370","number":370,"surah":7,"verses":[71],"verseLabel":"الأعراف: 71","question":"لماذا خُتمت المواجهة بـ﴿فانتظروا إني معكم من المنتظرين﴾؟","answer":"هو تهديد بعد تمام الحجة: انتظروا العذاب الذي استعجلتموه، وأنا معكم منتظر لوعد الله، وفيه ثقة بتحققه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص638–650.","url":""}]},{"id":"s7-371","number":371,"surah":7,"verses":[71],"verseLabel":"الأعراف: 71","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿ما نزّل الله بها من سلطان﴾ بالتشديد، وفي المواضع النظيرة: ﴿ما أنزل الله بها من سلطان﴾؟","answer":"جاء ﴿نزّل﴾ للمبالغة والتكثير في أول موضع من هذا التعبير، ليجري مجرى ذكر الجنس والتفصيل، وما في المواضع الأخرى بـ﴿أنزل﴾ كذكر النوع بعد الجنس.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-372","number":372,"surah":7,"verses":[72],"verseLabel":"الأعراف: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿فأنجيناه والذين معه برحمة منا﴾، فصرح بالرحمة؟","answer":"التصريح بـ﴿برحمة منا﴾ يبين أن النجاة فضل من الله ورحمته، لا استحقاقًا مستقلًا بالأعمال، وإن كانت صحبة الإيمان سببًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص650–657.","url":""}]},{"id":"s7-373","number":373,"surah":7,"verses":[72],"verseLabel":"الأعراف: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿وقطعنا دابر الذين كذبوا﴾؟","answer":"قطع الدابر استئصال آخر القوم وقطع أصلهم؛ فالكناية تصور هلاكًا عامًا لم يبق لهم بقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص650–657.","url":""}]},{"id":"s7-374","number":374,"surah":7,"verses":[72],"verseLabel":"الأعراف: 72","question":"لماذا عطف: ﴿وما كانوا مؤمنين﴾ بعد وصفهم بالتكذيب؟","answer":"عطف نفي الإيمان ليقرر أن التكذيب لم يكن عارضًا، بل صدر عن قوم لم يتلبسوا بالإيمان، وفيه بيان رسوخ سبب هلاكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص650–657.","url":""}]},{"id":"s7-375","number":375,"surah":7,"verses":[58],"verseLabel":"الأعراف: 72؛ هود: 58","question":"ما سرّ التعبير في قوله تعالى في الأعراف عن هود: ﴿فأنجيناه﴾، وفي هود: ﴿نجّينا هودًا﴾ بصيغة التفعيل؟","answer":"التشديد في ﴿نجّينا﴾ للمبالغة؛ لأن سورة هود أبرزت نجاتين: من الريح المهلكة ومن عذاب غليظ، أما الأعراف فأوجزت فجاءت ﴿أنجيناه﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص217–221.","url":""}]},{"id":"s7-376","number":376,"surah":7,"verses":[41,42],"verseLabel":"الأعراف: 72؛ فصلت: 16؛ الحاقة: 6–8؛ الذاريات: 41–42","question":"لماذا اكتفت الأعراف في هلاك عاد بقولها: ﴿وقطعنا دابر الذين كذبوا﴾، بينما سمّت سور أخرى الريح التي أهلكتهم؟","answer":"سياق الأعراف يجمع قصص الرسل في عرض موجز للعبرة، فاكتفى بكناية الاستئصال ﴿وقطعنا دابر﴾؛ أما السور الأخرى ففصلت أداة الهلاك وصفة الريح بحسب سياقاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص650–657؛ القرآن: فصلت 16، الحاقة 6–8، الذاريات 41–42.","url":""}]},{"id":"s7-377","number":377,"surah":7,"verses":[73],"verseLabel":"الأعراف: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿وإلى ثمود أخاهم صالحًا﴾ على نسق هود؟","answer":"الأخوة أخوة قوم ونسب، وفيها تقريب للنصيحة وقطع لتوهم طلب السيادة؛ فهو منهم يعرفون صدقه ولسانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص657–671.","url":""}]},{"id":"s7-378","number":378,"surah":7,"verses":[73],"verseLabel":"الأعراف: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿قد جاءتكم بينة من ربكم﴾، فجعل البينة آتية؟","answer":"صُوّرت البينة كأنها جاءت إليهم بنفسها لوضوح حضورها وقيامها بين أيديهم، مع التصريح بأنها من ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص657–671.","url":""}]},{"id":"s7-379","number":379,"surah":7,"verses":[73],"verseLabel":"الأعراف: 73","question":"لماذا أضيفت الناقة إلى الله: ﴿ناقة الله﴾؟","answer":"الإضافة للتشريف والتعظيم، وللدلالة على أنها آية خاصة خلقها الله على وجه خارق، لا أنها خارجة عن ملكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص657–671.","url":""}]},{"id":"s7-380","number":380,"surah":7,"verses":[73],"verseLabel":"الأعراف: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿لكم آية﴾ بتقديم ﴿لكم﴾؟","answer":"تقديم ﴿لكم﴾ يبرز اختصاصهم بالانتفاع بهذه الآية وقيام الحجة عليهم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص657–671.","url":""}]},{"id":"s7-381","number":381,"surah":7,"verses":[73],"verseLabel":"الأعراف: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿فذروها تأكل في أرض الله﴾؟","answer":"أي اتركوها حرة غير ممنوعة من الرعي؛ ووصف الأرض بأنها أرض الله يقرر ألا حق لهم في التضييق عليها فيما أباحه مالك الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص657–671.","url":""}]},{"id":"s7-382","number":382,"surah":7,"verses":[73],"verseLabel":"الأعراف: 73","question":"لماذا نُهي عن مجرد مسها بالسوء: ﴿ولا تمسوها بسوء﴾؟","answer":"النهي عن أدنى اتصال بسوء أبلغ في الحماية؛ فإذا حرم مجرد المس المؤذي كان العقر أولى بالتحريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص657–671.","url":""}]},{"id":"s7-383","number":383,"surah":7,"verses":[73],"verseLabel":"الأعراف: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿فيأخذكم عذاب أليم﴾، فجعل العذاب آخذًا؟","answer":"صُوّر العذاب كآخذ يقبض عليهم فلا يفلتون، وفي الفاء بيان سرعة ترتبه على مس الناقة بالسوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص657–671.","url":""}]},{"id":"s7-384","number":384,"surah":7,"verses":[73],"verseLabel":"الأعراف: 73","question":"ما سرّ اختلاف وصف العذاب في قصة ناقة صالح: ﴿عذاب أليم﴾ في الأعراف، و﴿عذاب قريب﴾ في هود، و﴿عذاب يوم عظيم﴾ في الشعراء؟","answer":"بالغ سياق الأعراف في الوعظ فناسبه الوعيد بـ﴿عذاب أليم﴾، ووُصف في هود بـ﴿قريب﴾ لاتصاله بقوله بعدها: ﴿تمتعوا في داركم ثلاثة أيام﴾، وزيد ﴿يوم﴾ في الشعراء لمناسبة قوله قبلها: ﴿لها شرب ولكم شرب يوم معلوم﴾.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف، المسألة 136؛ والإحالة المسجلة: صلاح الأمة.","url":""}]},{"id":"s7-385","number":385,"surah":7,"verses":[74],"verseLabel":"الأعراف: 74","question":"لماذا ذكّرهم بالاستخلاف من بعد عاد؟","answer":"ذكّرهم بالاستخلاف بعد عاد ليشكروا تمكين الله، وليعتبروا بهلاك من سبقهم حين كفروا وطغوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص671–705.","url":""}]},{"id":"s7-386","number":386,"surah":7,"verses":[74],"verseLabel":"الأعراف: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿وبوأكم في الأرض﴾، لا: أسكنكم؟","answer":"التبوئة ليست مجرد الإسكان، بل إنزالهم منازل مهيأة للاستقرار والانتفاع؛ فدل اللفظ على التمكين وحسن الإعداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص671–705.","url":""}]},{"id":"s7-387","number":387,"surah":7,"verses":[74],"verseLabel":"الأعراف: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿تتخذون من سهولها قصورًا وتنحتون الجبال بيوتًا﴾؟","answer":"جمع بين القصور في السهول والبيوت المنحوتة في الجبال ليصور سعة تمكينهم وعمرانهم وانتفاعهم بلين الأرض وصلابتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص671–705.","url":""}]},{"id":"s7-388","number":388,"surah":7,"verses":[74],"verseLabel":"الأعراف: 74","question":"لماذا عُدّي اتخاذ القصور بـ﴿من﴾، والنحت بلا حرف مماثل؟","answer":"في ﴿من سهولها﴾ معنى اتخاذ مادة القصور أو مواضعها من بعض السهول، أما الجبال فهي نفسها التي يقع عليها النحت فعدّي إليها مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص671–705.","url":""}]},{"id":"s7-389","number":389,"surah":7,"verses":[74],"verseLabel":"الأعراف: 74","question":"لماذا تكرر: ﴿فاذكروا آلاء الله﴾ كما في قصة عاد؟","answer":"تكرر الأمر لأن ثمود أنعمت كما أنعمت عاد بالاستخلاف والتمكين؛ فتكرر موجب الشكر والتحذير من عاقبة الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص671–705.","url":""}]},{"id":"s7-390","number":390,"surah":7,"verses":[74],"verseLabel":"الأعراف: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تعثوا في الأرض مفسدين﴾، أليس العثو فسادًا؟","answer":"﴿مفسدين﴾ حال مؤكدة تكشف هيئة العثو وعاقبته، وتبالغ في النهي عن شدة الفساد وانتشاره في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص671–705.","url":""}]},{"id":"s7-391","number":391,"surah":7,"verses":[74],"verseLabel":"الأعراف: 74","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وتنحتون الجبال بيوتًا﴾، وفي الشعراء: ﴿وتنحتون من الجبال بيوتًا﴾ بزيادة «من»؟","answer":"ذُكرت ﴿من﴾ في الأعراف قبلها في ﴿من سهولها قصورًا﴾ فاكتفي بها عند نحت الجبال، أما الشعراء فلم يسبق ما يغني عنها فجيء بـ﴿من الجبال﴾.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-392","number":392,"surah":7,"verses":[75],"verseLabel":"الأعراف: 75","question":"لماذا وُصف الملأ هنا بـ﴿الذين استكبروا﴾؟","answer":"وصفهم بالاستكبار لأنه العلة التي صدتهم عن البينة وحملتهم على استضعاف المؤمنين ومجادلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص671–705.","url":""}]},{"id":"s7-393","number":393,"surah":7,"verses":[75],"verseLabel":"الأعراف: 75","question":"ما سرّ توجيه الخطاب إلى ﴿لمن آمن منهم﴾، ففرقوا داخل المستضعفين؟","answer":"لم يكن كل المستضعفين مؤمنًا، فخص ﴿من آمن منهم﴾ لتمييز أهل الإيمان من غيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص671–705.","url":""}]},{"id":"s7-394","number":394,"surah":7,"verses":[75],"verseLabel":"الأعراف: 75","question":"ما سرّ سؤالهم: ﴿أتعلمون أن صالحًا مرسل من ربه﴾، دون: أتؤمنون؟","answer":"سؤالهم عن العلم تهكم يراد به زعزعة يقين المؤمنين؛ فسألوا عن ثبوت الرسالة كأنها دعوى بعيدة، لا طلبًا صادقًا للإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص671–705.","url":""}]},{"id":"s7-395","number":395,"surah":7,"verses":[75],"verseLabel":"الأعراف: 75","question":"ما سرّ جواب المؤمنين: ﴿إنا بما أرسل به مؤمنون﴾، دون الاكتفاء بنعم؟","answer":"أجابوا بجملة مؤكدة تثبت إيمانهم بما أرسل به، لا بمجرد شخصه؛ فكان أبلغ من «نعم» وأقوى في مواجهة الاستهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص671–705.","url":""}]},{"id":"s7-396","number":396,"surah":7,"verses":[76],"verseLabel":"الأعراف: 76","question":"ما سرّ جواب المستكبرين: ﴿إنا بالذي آمنتم به كافرون﴾؟","answer":"أعلنوا الكفر بنفس الرسالة التي أعلن المؤمنون الإيمان بها، فجاءت الصلة ﴿بالذي آمنتم به﴾ لإظهار المقابلة والعناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص671–705.","url":""}]},{"id":"s7-397","number":397,"surah":7,"verses":[76],"verseLabel":"الأعراف: 76","question":"ما سرّ تقديم ﴿بالذي آمنتم به﴾ على ﴿كافرون﴾؟","answer":"تقديم الجار والمجرور يبرز موضع كفرهم في مقابلة إيمان المستضعفين، ويفيد الاعتناء بهذا المتعلق وتخصيصه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص671–705.","url":""}]},{"id":"s7-398","number":398,"surah":7,"verses":[77],"verseLabel":"الأعراف: 77","question":"ما سرّ التعبير في قوله تعالى: ﴿فعقروا الناقة وعتوا عن أمر ربهم﴾، فجمع الفعل الحسي والتمرد القلبي؟","answer":"جمع بين عقر الناقة والعتو ليبين أن الجريمة الظاهرة صدرت عن تمرد باطن على أمر ربهم؛ فالفعل الحسي ثمرة الاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص705–731.","url":""}]},{"id":"s7-399","number":399,"surah":7,"verses":[77],"verseLabel":"الأعراف: 77","question":"لماذا عُدّي العتو بـ﴿عن﴾؟","answer":"عُدّي العتو بـ﴿عن﴾ لأنه تضمن معنى الإعراض والمجاوزة؛ فقد استكبروا منصرفين عن أمر ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص705–731.","url":""}]},{"id":"s7-400","number":400,"surah":7,"verses":[77],"verseLabel":"الأعراف: 77","question":"لماذا نادوا صالحًا باسمه مجردًا: ﴿يا صالح﴾؟","answer":"نادوه باسمه مجردًا استخفافًا وتحديًا، فلم يعترفوا له بوصف الرسالة، ثم استعجلوا ما توعدهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص705–731.","url":""}]},{"id":"s7-401","number":401,"surah":7,"verses":[77],"verseLabel":"الأعراف: 77","question":"ما سرّ تكرار تحديهم بقولهم: ﴿ائتنا بما تعدنا﴾ على نسق عاد؟","answer":"كرروا تحدي عاد نفسه، فسمّوا الوعيد وعدًا تهكمًا واستعجالًا للعذاب، وأضافوا ﴿إن كنت من المرسلين﴾ زيادةً في التكذيب بالرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص705–731.","url":""}]},{"id":"s7-402","number":402,"surah":7,"verses":[78],"verseLabel":"الأعراف: 78","question":"لماذا اختيرت ﴿الرجفة﴾ لعذاب ثمود؟","answer":"الرجفة زلزلة شديدة تضطرب لها الأرض والأبدان؛ فناسبت قومًا عتوا عن أمر ربهم، وصورت أخذهم أخذًا مفاجئًا لا ثبات معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص705–731.","url":""}]},{"id":"s7-403","number":403,"surah":7,"verses":[78],"verseLabel":"الأعراف: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿فأصبحوا في دارهم جاثمين﴾، مع تعدد مساكنهم؟","answer":"أُفردت ﴿دارهم﴾ لأن المراد بلدهم أو جنس مساكنهم، فكأن الديار المتعددة دار واحدة جمعهم فيها المصير نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص705–731.","url":""}]},{"id":"s7-404","number":404,"surah":7,"verses":[78],"verseLabel":"الأعراف: 78","question":"لماذا اختير ﴿جاثمين﴾؟","answer":"الجثوم لزوم المكان مع السقوط على الركب أو الصدر؛ فصوّرهم هامدين ملتصقين بالأرض بعد قوتهم وحركتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص705–731.","url":""}]},{"id":"s7-405","number":405,"surah":7,"verses":[78],"verseLabel":"الأعراف: 78","question":"ما سرّ التعبير في قوله تعالى عن ثمود في الأعراف: ﴿في دارهم جاثمين﴾ بالإفراد، وفي هود: ﴿في ديارهم جاثمين﴾ بالجمع؟","answer":"وحّد ﴿دارهم﴾ في الأعراف مع ذكر الرجفة، وهي زلزلة أرضهم الجامعة؛ وجمع ﴿ديارهم﴾ في هود مع الصيحة الآتية من السماء، إذ كان بلوغها أوسع وأبلغ.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-406","number":406,"surah":7,"verses":[79],"verseLabel":"الأعراف: 79","question":"ما سرّ خطاب صالح قومه بعد هلاكهم بقوله: ﴿يا قوم لقد أبلغتكم﴾؟","answer":"خطاب الهالكين تقريع لهم وإظهار لانقطاع العذر، كأنه وقف على منازلهم بعد هلاكهم يشهد أنهم لم يهلكوا قبل تمام البلاغ والنصح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص705–731.","url":""}]},{"id":"s7-407","number":407,"surah":7,"verses":[79],"verseLabel":"الأعراف: 79","question":"لماذا أفرد ﴿رسالة ربي﴾، بينما قال نوح وهود ﴿رسالات﴾؟","answer":"أفرد ﴿رسالة﴾ لأن أبرز ما حُكي في قصة صالح الأمر المتعلق بالناقة، فكأنها رسالة واحدة؛ أما القصص الأخرى فتعدد فيها المبلغ من الأوامر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص705–731.","url":""}]},{"id":"s7-408","number":408,"surah":7,"verses":[79],"verseLabel":"الأعراف: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكن لا تحبون الناصحين﴾، لا: لم تقبلوا نصحي؟","answer":"لم ينف مجرد قبولهم نصحه، بل أثبت فيهم نفرةً من جنس الناصحين؛ فالمشكلة فساد استعدادهم وكراهتهم لمن يريد لهم الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص705–731.","url":""}]},{"id":"s7-409","number":409,"surah":7,"verses":[80],"verseLabel":"الأعراف: 80","question":"لماذا بدأ قصة لوط بقوله: ﴿ولوطًا إذ قال لقومه﴾ من غير ﴿أخاهم﴾؟","answer":"لم يقل ﴿أخاهم﴾ لأن لوطًا لم يكن من نسب قومه الذين أُرسل إليهم، بخلاف هود وصالح وشعيب مع أقوامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص731–741.","url":""}]},{"id":"s7-410","number":410,"surah":7,"verses":[80],"verseLabel":"الأعراف: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿أتأتون الفاحشة﴾ بالتعريف؟","answer":"التعريف للعهد الذهني ولتفخيم شناعتها؛ فهي الفعلة البالغة الغاية في القبح التي يعرفون وصفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص731–741.","url":""}]},{"id":"s7-411","number":411,"surah":7,"verses":[80],"verseLabel":"الأعراف: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿ما سبقكم بها من أحد من العالمين﴾؟","answer":"نفى أن يكون أحد من العالمين سبقهم إليها، و﴿من﴾ تؤكد استغراق النفي؛ فجمع عليهم قبح الفاحشة وابتداعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص731–741.","url":""}]},{"id":"s7-412","number":412,"surah":7,"verses":[81],"verseLabel":"الأعراف: 81","question":"لماذا أكد: ﴿إنكم لتأتون الرجال شهوة﴾؟","answer":"أكد بـ﴿إن﴾ واللام لأن هذا تفصيل للفاحشة في مقام أشد تقريعًا وإنكارًا، ولأن فعلهم بلغ حدًا يحتاج إلى توكيد قبحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص741–749.","url":""}]},{"id":"s7-413","number":413,"surah":7,"verses":[81],"verseLabel":"الأعراف: 81","question":"لماذا نصب ﴿شهوة﴾، ولم يقل: بشهوة؟","answer":"نُصبت على المفعول لأجله أو الحال؛ أي تأتونهم لأجل الشهوة أو مشتهين، فينكشف أن المحرك شهوة مجردة لا مقصد مشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص741–749.","url":""}]},{"id":"s7-414","number":414,"surah":7,"verses":[81],"verseLabel":"الأعراف: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿من دون النساء﴾؟","answer":"أي متجاوزين النساء اللاتي جعلهن الله موضعًا للفطرة والإعفاف؛ فالتعبير يبرز العدول عن الطريق المشروع إلى ضده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص741–749.","url":""}]},{"id":"s7-415","number":415,"surah":7,"verses":[81],"verseLabel":"الأعراف: 81","question":"لماذا أضرب بقوله: ﴿بل أنتم قوم مسرفون﴾؟","answer":"﴿بل﴾ تترك مجرد وصف الفعل إلى كشف أصله في نفوسهم: الإسراف المتجاوز لكل حد هو الذي حملهم على تلك الفاحشة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص741–749.","url":""}]},{"id":"s7-416","number":416,"surah":7,"verses":[81],"verseLabel":"الأعراف: 81","question":"لماذا خُتم إنكار فاحشة قوم لوط في الأعراف بـ﴿قوم مسرفون﴾، وفي النمل بـ﴿قوم تجهلون﴾؟","answer":"عبّر في الأعراف بالاسم ﴿مسرفون﴾ موافقةً لفواصلها الاسمية السابقة، وفي النمل بالفعل ﴿تجهلون﴾ موافقةً لفواصلها الفعلية؛ والإسراف جهل والجهل إسراف.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-417","number":417,"surah":7,"verses":[82],"verseLabel":"الأعراف: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان جواب قومه إلا أن قالوا أخرجوهم﴾؟","answer":"أسلوب القصر يكشف أن ردهم الوحيد لم يكن حجة، بل قرار إقصاء: لم يجدوا جوابًا إلا إخراج الداعين إلى الطهارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص749–758.","url":""}]},{"id":"s7-418","number":418,"surah":7,"verses":[82],"verseLabel":"الأعراف: 82","question":"لماذا جُمِع لوط ومن معه في ﴿أخرجوهم من قريتكم﴾؟","answer":"جمعوه مع أهله ومن آمن به لأن إنكار الفاحشة والطهارة منها كان موقف جماعة، فصبوا تهديدهم على الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص749–758.","url":""}]},{"id":"s7-419","number":419,"surah":7,"verses":[82],"verseLabel":"الأعراف: 82","question":"لماذا أضافوا القرية إلى أنفسهم: ﴿قريتكم﴾؟","answer":"إضافتهم القرية إلى أنفسهم ادعاء للسلطان والاستئثار بها، وكأن الطاهرين غرباء لا حق لهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص749–758.","url":""}]},{"id":"s7-420","number":420,"surah":7,"verses":[82],"verseLabel":"الأعراف: 82","question":"ما سرّ تعبيرهم الساخر: ﴿إنهم أناس يتطهرون﴾؟","answer":"قلبوا المعيار فجعلوا التطهر تهمةً تستوجب الإخراج، وقالوها سخريةً؛ ففضحت العبارة انتكاس فطرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص749–758.","url":""}]},{"id":"s7-421","number":421,"surah":7,"verses":[82],"verseLabel":"الأعراف: 82","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وما كان جواب قومه﴾ بالواو، وفي النمل والعنكبوت: ﴿فما كان جواب قومه﴾ بالفاء؟","answer":"جاءت الواو في الأعراف لأن ما قبلها اسم ﴿مسرفون﴾، أما الفاء فتلائم التعقيب بعد الأفعال في النمل والعنكبوت.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-422","number":422,"surah":7,"verses":[82],"verseLabel":"الأعراف: 82","question":"ما سرّ التعبير في الأعراف: ﴿أخرجوهم من قريتكم﴾ بالضمير، وفي النمل: ﴿أخرجوا آل لوط من قريتكم﴾ بالاسم الظاهر؟","answer":"جاء الضمير في الأعراف كنايةً بيّنها التصريح ﴿آل لوط﴾ في النمل؛ وقيل: صُرّح في النازل أولًا ثم كُنّي في النازل بعده.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-423","number":423,"surah":7,"verses":[83],"verseLabel":"الأعراف: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿فأنجيناه وأهله إلا امرأته﴾، دون أن يقال: وزوجه؟","answer":"اختير ﴿امرأته﴾ لأن الزوجية الحقيقية تقتضي الموافقة والألفة، وقد قطعت خيانتها في الدين هذه الصلة المعنوية وإن بقي عقد النكاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص758–764.","url":""}]},{"id":"s7-424","number":424,"surah":7,"verses":[83],"verseLabel":"الأعراف: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿كانت من الغابرين﴾، لا: فهلكت؟","answer":"﴿الغابرون﴾ الباقون خلف الراحلين؛ فصورتها ممن تخلف مع قومها عن ركب النجاة فشملها الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص758–764.","url":""}]},{"id":"s7-425","number":425,"surah":7,"verses":[83],"verseLabel":"الأعراف: 83","question":"ما سرّ التعبير في قوله تعالى عن امرأة لوط في الأعراف: ﴿كانت من الغابرين﴾، وفي النمل: ﴿قدرناها من الغابرين﴾؟","answer":"﴿كانت﴾ تبين صيرورتها في الهالكين كما سبق في علم الله، و﴿قدرناها﴾ في النمل تصرح بأن ذلك كان بتقدير الله؛ فالثاني يبين منشأ الأول.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-426","number":426,"surah":7,"verses":[84],"verseLabel":"الأعراف: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿وأمطرنا عليهم مطرًا﴾، فكرر مادة المطر؟","answer":"جمع الفعل ومصدره للتوكيد والتهويل، ولبيان أن ما نزل عليهم مطر خاص غير معهود: حجارة العذاب لا ماء الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص764–769.","url":""}]},{"id":"s7-427","number":427,"surah":7,"verses":[84],"verseLabel":"الأعراف: 84","question":"لماذا عُدّي المطر بـ﴿على﴾؟","answer":"عُدّي بـ﴿على﴾ لأن المطر انصب من فوقهم واستعلى عليهم، وفي الحرف إيحاء بإحاطة العذاب وقهره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص764–769.","url":""}]},{"id":"s7-428","number":428,"surah":7,"verses":[84],"verseLabel":"الأعراف: 84","question":"لماذا خُتمت القصة بـ﴿فانظر كيف كان عاقبة المجرمين﴾؟","answer":"الخاتمة تحول الخبر إلى عبرة مشاهدة، وتأمر بالنظر في مصير من أجرموا ليحذر المخاطبون طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص764–769.","url":""}]},{"id":"s7-429","number":429,"surah":7,"verses":[84],"verseLabel":"الأعراف: 84","question":"لماذا خُتم هلاك قوم لوط في الأعراف بـ﴿فانظر كيف كان عاقبة المجرمين﴾، وفي الصافات بـ﴿فساء مطر المنذرين﴾؟","answer":"خاتمة الأعراف ﴿فانظر﴾ تناسب ما بعدها ﴿وانظروا كيف كان عاقبة المفسدين﴾، أما الصافات فختمت بذم المطر نفسه في سياق الإنذار.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-430","number":430,"surah":7,"verses":[85],"verseLabel":"الأعراف: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿وإلى مدين أخاهم شعيبًا﴾؟","answer":"الأخوة أخوة نسب وقوم، وفيها تقريب للنصح وإقامة للحجة بلسان رجل يعرفونه، لا أخوة موافقة في العقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص769–784.","url":""}]},{"id":"s7-431","number":431,"surah":7,"verses":[85],"verseLabel":"الأعراف: 85","question":"لماذا انتقل شعيب من التوحيد إلى ﴿أوفوا الكيل والميزان﴾؟","answer":"بعد تقرير أصل التوحيد انتقل إلى أبرز فساد عملي اشتهروا به؛ لأن صحة العبادة تثمر العدل في معاملات الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص769–784.","url":""}]},{"id":"s7-432","number":432,"surah":7,"verses":[85],"verseLabel":"الأعراف: 85","question":"لماذا جمع بين الكيل والميزان؟","answer":"جمعهما ليستوعب وسائل تقدير الحقوق: المكيلات والموزونات، فلا يبقى باب للتطفيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص769–784.","url":""}]},{"id":"s7-433","number":433,"surah":7,"verses":[85],"verseLabel":"الأعراف: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تبخسوا الناس أشياءهم﴾، دون أن يقال: أموالهم؟","answer":"﴿أشياءهم﴾ أعم من الأموال؛ فيشمل كل حق مادي أو معنوي يجب توفيته، قليلًا كان أو كثيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص769–784.","url":""}]},{"id":"s7-434","number":434,"surah":7,"verses":[85],"verseLabel":"الأعراف: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿بعد إصلاحها﴾ كما في الآية 56؟","answer":"نهى عن إفساد الأرض بعد أن أصلحها الله بالشرائع والنظام والأمن، كما سبق في الآية 56؛ فالجريمة أشد بعد قيام الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص769–784.","url":""}]},{"id":"s7-435","number":435,"surah":7,"verses":[85],"verseLabel":"الأعراف: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلكم خير لكم إن كنتم مؤمنين﴾؟","answer":"الإشارة تجمع التوحيد وإيفاء الحقوق وترك الفساد، وهذه خير لهم في الدنيا والآخرة إن صدق إيمانهم وعملوا بمقتضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص769–784.","url":""}]},{"id":"s7-436","number":436,"surah":7,"verses":[86],"verseLabel":"الأعراف: 86","question":"لماذا نهى: ﴿ولا تقعدوا بكل صراط توعدون﴾؟","answer":"نهى عن ترصد الطرق لتخويف الناس ومنعهم من شعيب ودين الله؛ فالقعود تصوير للملازمة والتعمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص784–796.","url":""}]},{"id":"s7-437","number":437,"surah":7,"verses":[86],"verseLabel":"الأعراف: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿بكل صراط﴾ بالإفراد بعد ﴿كل﴾؟","answer":"﴿كل﴾ تضاف إلى المفرد لإفادة العموم، أي لا تقعدوا على أي طريق من الطرق؛ فالإفراد لا يحد المعنى بطريق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص784–796.","url":""}]},{"id":"s7-438","number":438,"surah":7,"verses":[86],"verseLabel":"الأعراف: 86","question":"لماذا ترتبت الأفعال: ﴿توعدون وتصدون... وتبغونها عوجًا﴾؟","answer":"يبدأ فسادهم بتهديد السالك، ثم منعه من سبيل الله، ثم محاولة تصوير السبيل المستقيم معوجة؛ فترقى من الإرهاب إلى الصد ثم التشويه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص784–796.","url":""}]},{"id":"s7-439","number":439,"surah":7,"verses":[86],"verseLabel":"الأعراف: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿واذكروا إذ كنتم قليلًا فكثركم﴾؟","answer":"ذكّرهم بحال القلة ثم بما أحدثه الله من التكثير؛ والفاء تصور سرعة تحول النعمة بقدرته، وهو موجب للشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص784–796.","url":""}]},{"id":"s7-440","number":440,"surah":7,"verses":[86],"verseLabel":"الأعراف: 86","question":"لماذا خُتمت بـ﴿وانظروا كيف كان عاقبة المفسدين﴾؟","answer":"أمرهم أن يعتبروا بمصائر المفسدين قبلهم؛ فمن سنن الله أن الإفساد بعد الإصلاح ينتهي إلى الخسران والهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص784–796.","url":""}]},{"id":"s7-441","number":441,"surah":7,"verses":[87],"verseLabel":"الأعراف: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن كان طائفة منكم آمنوا... وطائفة لم يؤمنوا﴾، فكرر ﴿طائفة﴾؟","answer":"كرر ﴿طائفة﴾ ليفصل الفريقين ويظهر استقلال كل منهما بحكمه وموقفه، فلا يلتبس المؤمن بغير المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص796–807.","url":""}]},{"id":"s7-442","number":442,"surah":7,"verses":[87],"verseLabel":"الأعراف: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿بِالذي أرسلت به﴾ بالبناء للمجهول؟","answer":"بُني ﴿أرسلت﴾ للمجهول لأن المقصود ما حُمّل من الرسالة لا تعيين المرسِل، وهو معلوم أنه الله من السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص796–807.","url":""}]},{"id":"s7-443","number":443,"surah":7,"verses":[87],"verseLabel":"الأعراف: 87","question":"لماذا أمر الفريقين بالصبر: ﴿فاصبروا حتى يحكم الله بيننا﴾؟","answer":"أمر الجميع بانتظار حكم الله لأن المؤمنين ثبتوا على الحق، والمكذبين أصروا؛ فبعد البلاغ لا يفصل النزاع إلا حكم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص796–807.","url":""}]},{"id":"s7-444","number":444,"surah":7,"verses":[87],"verseLabel":"الأعراف: 87","question":"لماذا خُتمت بـ﴿وهو خير الحاكمين﴾؟","answer":"الخاتمة تثبت عدل الحكم وكماله وتطمئن المؤمنين؛ فلا حاكم أصدق ولا أعلم ولا أعدل من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص796–807.","url":""}]},{"id":"s7-445","number":445,"surah":7,"verses":[88],"verseLabel":"الأعراف: 88","question":"لماذا وُصف الملأ هنا بـ﴿الذين استكبروا﴾، ولم يقتصر على ﴿الملأ﴾؟","answer":"وصفهم بالاستكبار لكشف الدافع إلى تهديد شعيب والمؤمنين؛ فالتعالي منعهم من قبول الحجة وحملهم على الإكراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص10–24.","url":""}]},{"id":"s7-446","number":446,"surah":7,"verses":[88],"verseLabel":"الأعراف: 88","question":"لماذا قدّموا إخراج شعيب على إعادته في ملتهم: ﴿لنخرجنك... أو لتعودن﴾؟","answer":"قدموا الإخراج لأنه العقوبة العاجلة التي يملكونها، ثم جعلوا الرجوع في ملتهم بديلًا يمنعها؛ فخيّروهم بين الوطن والعقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص10–24.","url":""}]},{"id":"s7-447","number":447,"surah":7,"verses":[88],"verseLabel":"الأعراف: 88","question":"لماذا أكّدوا التهديد باللام والنون: ﴿لنخرجنك﴾ و﴿لتعودن﴾؟","answer":"اللام والنون الثقيلة توكد تصميمهم على إنفاذ أحد الأمرين، وتصور شدة التهديد والتسلط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص10–24.","url":""}]},{"id":"s7-448","number":448,"surah":7,"verses":[88],"verseLabel":"الأعراف: 88","question":"ما سرّ تعبيرهم بـ﴿شعيب والذين آمنوا معك﴾، فأظهروا اسمه ووصفوا أتباعه بالمعية؟","answer":"صرحوا باسم شعيب إهانةً وتعيينًا لرأس الدعوة، ووصفوا المؤمنين بالمعية لإظهار أنهم أتباع مجتمعون حوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص10–24.","url":""}]},{"id":"s7-449","number":449,"surah":7,"verses":[88],"verseLabel":"الأعراف: 88","question":"لماذا حُذف متعلَّق ﴿آمنوا﴾، فلم يقل: آمنوا بك؟","answer":"حذف متعلق الإيمان ليعم الإيمان بالله ورسوله وما أرسل به، فلا يحصره في مجرد التصديق بشعيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص10–24.","url":""}]},{"id":"s7-450","number":450,"surah":7,"verses":[88],"verseLabel":"الأعراف: 88","question":"ما وجه قولهم لشعيب: ﴿لتعودن في ملتنا﴾ مع أنه نبي لم يكن على ملتهم؟","answer":"العود قد يستعمل بمعنى الصيرورة والدخول، فيكون المعنى: لتصيرن في ملتنا؛ وقيل إن الخطاب غلّب أتباعه الذين كانوا فيها، فلا يلزم منه أن شعيبًا كان عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص10–24.","url":""}]},{"id":"s7-451","number":451,"surah":7,"verses":[88],"verseLabel":"الأعراف: 88","question":"لماذا عُدّي ﴿لتعودن﴾ بـ﴿في﴾: ﴿في ملتنا﴾؟","answer":"عُدّي العود بـ﴿في﴾ لتصوير الملة كالحيز المحيط بمن يدخل فيها ويتمكن منها، وفيه بيان إرادتهم دمج المؤمنين في باطلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص10–24.","url":""}]},{"id":"s7-452","number":452,"surah":7,"verses":[88],"verseLabel":"الأعراف: 88","question":"لماذا أجابهم شعيب باستفهام: ﴿أولو كنا كارهين﴾؟","answer":"الاستفهام إنكاري: أتجبروننا على ملتكم ولو كنا شديدي الكراهة لها؟ فهو رفض للإكراه وإظهار لبطلان عرضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص10–24.","url":""}]},{"id":"s7-453","number":453,"surah":7,"verses":[88],"verseLabel":"الأعراف: 88","question":"لماذا اختيرت ﴿لو﴾ في ﴿أولو كنا كارهين﴾، وحُذف جوابها؟","answer":"﴿لو﴾ تدخل على الحالة المفروضة المستبعدة، وحذف جوابها لدلالة التهديد عليه: أَنعود أو تُعيدوننا ولو كنا كارهين؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص10–24.","url":""}]},{"id":"s7-454","number":454,"surah":7,"verses":[88],"verseLabel":"الأعراف: 88","question":"لماذا عبّر بـ﴿كارهين﴾ لا بـ«مكرهين»؟","answer":"﴿كارهين﴾ تصف نفرة قلوبهم من الملة نفسها، وهي أبلغ هنا من «مكرهين» التي تصف ضغطًا خارجيًا مع احتمال عدم كراهة الشيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص10–24.","url":""}]},{"id":"s7-455","number":455,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿قد افترينا على الله كذبًا﴾، فجمع بين الافتراء والكذب؟","answer":"الافتراء هو اختلاق الكذب عمدًا ونسبته إلى الله؛ فذكر ﴿كذبًا﴾ يصرح بحقيقة الافتراء ويبالغ في تقبيحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-456","number":456,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"لماذا جاء الشرط بـ﴿إن عدنا﴾ مع أن الخصوم قالوا: ﴿لتعودن﴾؟","answer":"جاء الشرط لبيان المحال المترتب على فرض رجوعهم: إن وقع العود الذي تطلبونه فقد افترينا؛ وليس فيه تردد في ثباتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-457","number":457,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"لماذا كرر لفظ العود في آيتين متتابعتين؟","answer":"كرر العود لمواجهة لفظ تهديدهم بلفظه، وبيان ما يلزم منه دينيًا: ما سموه عودًا هو افتراء على الله بعد النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-458","number":458,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿بعد إذ نجانا الله منها﴾، دون أن يقال: بعد أن خرجنا منها؟","answer":"سمّى مفارقة الملة نجاةً لأن الشرك هلاك، ولأن الخروج من سلطانه وفتنته فضل من الله لا مجرد انتقال بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-459","number":459,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"لماذا أعاد اسم الجلالة في ﴿نجانا الله منها﴾ بعد ﴿افترينا على الله﴾؟","answer":"أعيد اسم الجلالة لإظهار طرفي الجريمة والنعمة: العود افتراء على الله، والنجاة كانت من الله؛ فلا يقابل فضله بالكذب عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-460","number":460,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يكون لنا أن نعود فيها﴾ بدل «ولن نعود فيها»؟","answer":"هذا التركيب ينفي الاستحقاق والإمكان اللائق بهم، لا مجرد نية مستقبلية؛ أي لا يصح ولا يستقيم لنا أن نعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-461","number":461,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"لماذا استثنى: ﴿إلا أن يشاء الله ربنا﴾ بعد التصريح باستحالة العود؟","answer":"الاستثناء تفويض إلى مشيئة الله وتأدب معه وبراءة من الاتكال على النفس؛ لا يدل على احتمال أن يشاء الله لهم الكفر، فالله لا يرضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-462","number":462,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"لماذا وصف الله هنا بـ﴿ربنا﴾؟","answer":"اسم الرب يستحضر الولاية والتربية والحفظ؛ فهو الذي نجاهم ويتولى تثبيتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-463","number":463,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"لماذا كرر ﴿ربنا﴾ في ﴿إلا أن يشاء الله ربنا وسع ربنا كل شيء علمًا﴾؟","answer":"كرر ﴿ربنا﴾ تعظيمًا وتلذذًا بالربوبية، وربطًا بين مشيئته المحيطة وعلمه الذي وسع كل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-464","number":464,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿وسع ربنا كل شيء علمًا﴾، فجعل العلم تمييزًا للسعة؟","answer":"نُصب ﴿علمًا﴾ تمييزًا يفسر جهة السعة: ليست سعة مكان، بل إحاطة علم بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-465","number":465,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"لماذا قدّم الجار والمجرور في ﴿على الله توكلنا﴾؟","answer":"قدم ﴿على الله﴾ لإفادة الاختصاص والاهتمام: عليه وحده اعتمدنا في الثبات والحماية والحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-466","number":466,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿ربنا افتح بيننا وبين قومنا بالحق﴾، واختار «افتح» بمعنى احكم؟","answer":"الفتح أصله إزالة الإغلاق والفصل بين شيئين، فاستعير للحكم الذي يكشف الحق ويفصل النزاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-467","number":467,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿بيننا وبين قومنا﴾ مع أنهم قومه؟","answer":"قال ﴿قومنا﴾ مع خصومتهم إبقاءً لرابطة النسب وإظهارًا للنصح، أما المباينة فهي في الإيمان والكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-468","number":468,"surah":7,"verses":[89],"verseLabel":"الأعراف: 89","question":"لماذا خُتم الدعاء بـ﴿وأنت خير الفاتحين﴾ لا «خير الحاكمين» كما في الآية 87؟","answer":"لما دعا بلفظ ﴿افتح﴾ ناسبت الخاتمة ﴿خير الفاتحين﴾، أما الآية 87 فذكرت الحكم صراحة فختمت بـ﴿خير الحاكمين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص25–38.","url":""}]},{"id":"s7-469","number":469,"surah":7,"verses":[90],"verseLabel":"الأعراف: 90","question":"لماذا أعيد وصف القادة بـ﴿الملأ الذين كفروا من قومه﴾ بعد وصفهم بالاستكبار؟","answer":"أعاد وصف الكفر لتسجيل حقيقة موقفهم بعد تهديدهم، ولأن خطابهم التالي تحريض عقدي يصد الناس عن اتباع شعيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص39–43.","url":""}]},{"id":"s7-470","number":470,"surah":7,"verses":[90],"verseLabel":"الأعراف: 90","question":"ما سرّ تعبيرهم بـ﴿لئن اتبعتم شعيبًا﴾ دون: لئن آمنتم به؟","answer":"الاتباع أعم من مجرد التصديق؛ فهو الإيمان والانقياد والسير على طريقه، ولذلك خوّفوا قومهم من آثاره العملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص39–43.","url":""}]},{"id":"s7-471","number":471,"surah":7,"verses":[90],"verseLabel":"الأعراف: 90","question":"لماذا صرّحوا باسم شعيب بدل الضمير؟","answer":"صرحوا باسمه لتشويه شخصه وتنفير الناس منه، وليجعلوا الخسارة معلقة باتباعه خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص39–43.","url":""}]},{"id":"s7-472","number":472,"surah":7,"verses":[90],"verseLabel":"الأعراف: 90","question":"لماذا أكدوا جوابهم بـ﴿إنكم إذًا لخاسرون﴾؟","answer":"أكدوا بـ﴿إن﴾ واللام، وجاءت ﴿إذًا﴾ جزاءً للاتباع المزعوم؛ فصوّروا الخسران نتيجة محققة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص39–43.","url":""}]},{"id":"s7-473","number":473,"surah":7,"verses":[90],"verseLabel":"الأعراف: 90","question":"لماذا وصفوا المؤمنين بالخاسرين مع أن الخاسرين الحقيقيين هم المكذبون في الآية 92؟","answer":"سموا المؤمنين خاسرين لقلب الحقائق وتخويفهم من فوات مصالح الدنيا؛ ثم رد السياق القصر عليهم فأثبت أن المكذبين هم الخاسرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص39–43.","url":""}]},{"id":"s7-474","number":474,"surah":7,"verses":[91],"verseLabel":"الأعراف: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿فأخذتهم الرجفة﴾، فجعل الرجفة آخذة لهم؟","answer":"جُعلت الرجفة آخذةً استعارةً لشدة إحاطتها بهم وتمكنها منهم، كآخذ لا يترك مأخوذه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص44–51.","url":""}]},{"id":"s7-475","number":475,"surah":7,"verses":[91],"verseLabel":"الأعراف: 91","question":"لماذا اختيرت ﴿الرجفة﴾ لعذاب قوم شعيب؟","answer":"الرجفة تناسب زعزعة أرضهم وأبدانهم بعد استكبارهم وثباتهم على الباطل، وهي من جنس العذاب الذي أخذ ثمود أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص44–51.","url":""}]},{"id":"s7-476","number":476,"surah":7,"verses":[91],"verseLabel":"الأعراف: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿فأصبحوا﴾ مع أن الأخذ قد يكون في غير الصباح؟","answer":"﴿أصبحوا﴾ قد يراد بها الدخول في الصباح أو الصيرورة؛ والمقصود ظهور حالهم بعد العذاب جاثمين لا حراك بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص44–51.","url":""}]},{"id":"s7-477","number":477,"surah":7,"verses":[91],"verseLabel":"الأعراف: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿في دارهم﴾ بالإفراد مع أنهم جماعة؟","answer":"أُفردت الدار بمعنى البلد أو جنس المساكن، فوحد المصير مساكن الجماعة كأنها دار واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص44–51.","url":""}]},{"id":"s7-478","number":478,"surah":7,"verses":[91],"verseLabel":"الأعراف: 91","question":"لماذا صُوّر هلاكهم بقوله: ﴿جاثمين﴾؟","answer":"الجثوم لزوم الأرض بلا حركة؛ فصور أجسادهم ساقطة هامدة بعد قوتهم وتهديدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص44–51.","url":""}]},{"id":"s7-479","number":479,"surah":7,"verses":[91],"verseLabel":"الأعراف: 91","question":"ما مناسبة ﴿جاثمين﴾ لتهديدهم شعيبًا بالإخراج من القرية؟","answer":"هددوا شعيبًا بالإخراج من القرية، فعوقبوا بأن ثبتوا جثثًا في دارهم؛ لم يخرج هو، وزال سلطان من أراد إخراجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص44–51.","url":""}]},{"id":"s7-480","number":480,"surah":7,"verses":[92],"verseLabel":"الأعراف: 92","question":"لماذا أعيد الموصول: ﴿الذين كذبوا شعيبًا﴾ مرتين؟","answer":"تكرار الموصول يثبت الحكمين للفئة نفسها ويشهر سبب مصيرها: تكذيب شعيب، لا عارض آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص52–56.","url":""}]},{"id":"s7-481","number":481,"surah":7,"verses":[92],"verseLabel":"الأعراف: 92","question":"لماذا صُرّح باسم شعيب مرة أخرى بدل الضمير؟","answer":"إظهار اسم شعيب يعتني بتبرئته ويعيد الصلة التي استحقوا بها العقوبة، بدل ضمير قد يضعف هذا التسجيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص52–56.","url":""}]},{"id":"s7-482","number":482,"surah":7,"verses":[92],"verseLabel":"الأعراف: 92","question":"لماذا شُبّهوا بمن لم يقيموا في الديار: ﴿كأن لم يغنوا فيها﴾؟","answer":"مُحيت آثارهم وانقطع أنسهم بالديار حتى صار حالها كأنهم لم يقيموا فيها يومًا، بعد ادعائهم ملك القرية والتمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص52–56.","url":""}]},{"id":"s7-483","number":483,"surah":7,"verses":[92],"verseLabel":"الأعراف: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿يغنوا﴾، دون أن يقال: يسكنوا؟","answer":"الغِنى بالمكان طول الإقامة مع العيش والأنس، فهو أبلغ من مجرد السكن؛ ونفيه يصور زوالهم وزوال آثار نعمتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص52–56.","url":""}]},{"id":"s7-484","number":484,"surah":7,"verses":[92],"verseLabel":"الأعراف: 92","question":"ما سرّ تقديم المكذبون في ﴿الذين كذبوا شعيبًا كانوا هم الخاسرين﴾؟","answer":"قدم الموصول للتشويق إلى الحكم ولحصر الخسران في المكذبين، ردًا على قولهم إن أتباع شعيب هم الخاسرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص52–56.","url":""}]},{"id":"s7-485","number":485,"surah":7,"verses":[92],"verseLabel":"الأعراف: 92","question":"لماذا أُتي بضمير الفصل ﴿هم﴾؟","answer":"ضمير الفصل ﴿هم﴾ يفيد القصر والتوكيد: هم الخاسرون حقًا، لا المؤمنون الذين رموهم بالخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص52–56.","url":""}]},{"id":"s7-486","number":486,"surah":7,"verses":[92],"verseLabel":"الأعراف: 92","question":"لماذا خُتمت القصة بـ﴿الخاسرين﴾ بعد أن نسبوا الخسران إلى أتباع شعيب؟","answer":"جاءت الخاتمة ردًا مطابقًا لمقالتهم؛ فقلبت دعواهم وأثبتت أن من فقد نفسه ودياره هو الخاسر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص52–56.","url":""}]},{"id":"s7-487","number":487,"surah":7,"verses":[93],"verseLabel":"الأعراف: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿فتولى عنهم﴾ بالفاء عقب هلاكهم؟","answer":"الفاء تدل على أن توليه عنهم أعقب وقوع العذاب، فغادر موضعهم بعد أن انتهت دعوتهم وقضي بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص57–64.","url":""}]},{"id":"s7-488","number":488,"surah":7,"verses":[93],"verseLabel":"الأعراف: 93","question":"ما سرّ خطاب شعيب قومه بعد هلاكهم بقوله: ﴿يا قوم لقد أبلغتكم﴾؟","answer":"خاطبهم بعد الهلاك تقريعًا وتحسرًا وإظهارًا لتمام الحجة، كمن يقف على ديارهم ويعلن أنهم رفضوا البلاغ والنصح.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص57–64.","url":""}]},{"id":"s7-489","number":489,"surah":7,"verses":[93],"verseLabel":"الأعراف: 93","question":"ما سرّ تعبير شعيب بالماضي ﴿أبلغتكم﴾، وتعبير نوح بالمضارع ﴿أبلغكم﴾؟","answer":"جاء الماضي عند ختام الرسالة ودنو العذاب وبعد وقوعه، أما مضارع نوح فورد في ابتداء دعوته دالًا على الاستمرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص57–64.","url":""}]},{"id":"s7-490","number":490,"surah":7,"verses":[93],"verseLabel":"الأعراف: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿رسالات ربي﴾ بالجمع، وقال صالح: ﴿رسالة ربي﴾ بالإفراد؟","answer":"جُمعت رسالات شعيب لتعدد ما أمرهم به بعد التوحيد من الوفاء وترك البخس والإفساد والصد؛ وأُفردت رسالة صالح لأن أبرز قصته أمر الناقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص57–64.","url":""}]},{"id":"s7-491","number":491,"surah":7,"verses":[93],"verseLabel":"الأعراف: 93","question":"لماذا أضاف الرب إلى نفسه: ﴿ربي﴾، بينما قال في الآية 89: ﴿ربنا﴾؟","answer":"قال ﴿ربي﴾ في مقام شهادته على أداء رسالته الخاصة، وقال ﴿ربنا﴾ حين جمع نفسه والمؤمنين في الدعاء والتوكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص57–64.","url":""}]},{"id":"s7-492","number":492,"surah":7,"verses":[93],"verseLabel":"الأعراف: 93","question":"لماذا عُدّي ﴿نصحت﴾ باللام: ﴿ونصحت لكم﴾؟","answer":"اللام تبين أن نصحه خالص لمنفعتهم ومصلحتهم، لا طلبًا لحظ نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص57–64.","url":""}]},{"id":"s7-493","number":493,"surah":7,"verses":[93],"verseLabel":"الأعراف: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿فكيف آسى﴾ بالاستفهام لا «فلا آسى»؟","answer":"الاستفهام إنكاري بمعنى انتفاء الأسى بعد قيام الحجة وإصرارهم على الكفر؛ وكيف يحزن على من اختار سبب هلاكه؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص57–64.","url":""}]},{"id":"s7-494","number":494,"surah":7,"verses":[93],"verseLabel":"الأعراف: 93","question":"لماذا صدّر الاستفهام بالفاء: ﴿فكيف آسى﴾؟","answer":"الفاء تفرع انتفاء الأسى على ما قبلها: لقد بلّغ ونصح فكذبوا، فكيف يبقى موضع للحزن عليهم بعد ذلك؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص57–64.","url":""}]},{"id":"s7-495","number":495,"surah":7,"verses":[93],"verseLabel":"الأعراف: 93","question":"لماذا عبّر بالمضارع ﴿آسى﴾ بعد الأفعال الماضية: تولى، أبلغت، نصحت؟","answer":"المضارع يستحضر حالة الأسى ويجدد صورتها ثم ينفيها، بخلاف الأفعال الماضية التي سجلت ما تم من البلاغ والنصح.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص57–64.","url":""}]},{"id":"s7-496","number":496,"surah":7,"verses":[93],"verseLabel":"الأعراف: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿على قوم كافرين﴾ فنكّر «قومًا» ووصفهم بالكفر؟","answer":"التنكير مع وصف الكفر يذمهم بهذا الوصف ويبين أن سبب عدم الأسى ليس القرابة، بل كونهم قومًا راسخين في الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص57–64.","url":""}]},{"id":"s7-497","number":497,"surah":7,"verses":[94],"verseLabel":"الأعراف: 94","question":"لماذا انتقل السياق من قصة شعيب إلى قاعدة عامة: ﴿وما أرسلنا في قرية من نبي﴾؟","answer":"بعد عرض نماذج الرسل وأقوامهم انتقل إلى السنة العامة التي تجمعها: الابتلاء بالبأساء والضراء لعل أهل القرى يتضرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص65–73.","url":""}]},{"id":"s7-498","number":498,"surah":7,"verses":[94],"verseLabel":"الأعراف: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿في قرية﴾ لا «إلى قرية»؟","answer":"﴿في قرية﴾ تصور بعثة النبي وقيامه داخل مجتمعها ومخالطته أهلها، لا مجرد توجيه رسالة من خارجها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص65–73.","url":""}]},{"id":"s7-499","number":499,"surah":7,"verses":[94],"verseLabel":"الأعراف: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿من نبي﴾ بزيادة ﴿من﴾؟","answer":"﴿من﴾ زائدة لتوكيد الاستغراق بعد النفي: ما أرسل الله نبيًا واحدًا في قرية إلا جرت سنته المذكورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص65–73.","url":""}]},{"id":"s7-500","number":500,"surah":7,"verses":[94],"verseLabel":"الأعراف: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا أخذنا أهلها﴾ فجاء الاستثناء عقب نفي الإرسال؟","answer":"الاستثناء يبين سنة ملازمة لإرسال الرسل إلى المكذبين: لا يقع إرسال نبي في قرية إلا أعقبته تربية أهلها بالشدة لعلهم يضرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص65–73.","url":""}]},{"id":"s7-501","number":501,"surah":7,"verses":[94],"verseLabel":"الأعراف: 94","question":"لماذا أسند الأخذ إلى الله بصيغة الجمع: ﴿أخذنا﴾؟","answer":"صيغة الجمع للتعظيم وإظهار القدرة؛ فالأخذ فعل الله الذي تنفذه جنوده وأسبابه المسخرة بأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص65–73.","url":""}]},{"id":"s7-502","number":502,"surah":7,"verses":[94],"verseLabel":"الأعراف: 94","question":"لماذا جمع بين ﴿البأساء والضراء﴾؟","answer":"جمعهما لاستيعاب ألوان الشدة في أحوالهم: ما يصيب المعاش والأموال وما يصيب الأبدان والأنفس، حتى تستيقظ القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص65–73.","url":""}]},{"id":"s7-503","number":503,"surah":7,"verses":[94],"verseLabel":"الأعراف: 94","question":"ما الفرق البياني بين ﴿البأساء﴾ و﴿الضراء﴾؟","answer":"البأساء شدة الفقر وضيق العيش وما يتصل بالأموال، والضراء ما يضر الأبدان من مرض وألم؛ وباجتماعهما يعم الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص65–73.","url":""}]},{"id":"s7-504","number":504,"surah":7,"verses":[94],"verseLabel":"الأعراف: 94","question":"لماذا خُتم الابتلاء بقوله: ﴿لعلهم يضرعون﴾؟","answer":"جعل غاية الأخذ أن يتذللوا لله ويرجعوا إليه؛ فالابتلاء تربية وإنذار قبل أن يكون عقوبة استئصال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص65–73.","url":""}]},{"id":"s7-505","number":505,"surah":7,"verses":[94],"verseLabel":"الأعراف: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿يضرعون﴾، دون أن يقال: يدعون؟","answer":"الضراعة أخص من الدعاء؛ فهي تذلل وانكسار وإظهار افتقار مع الدعاء، وهو الأثر المقصود من الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص65–73.","url":""}]},{"id":"s7-506","number":506,"surah":7,"verses":[95],"verseLabel":"الأعراف: 95","question":"لماذا افتتحت الآية بـ﴿ثم﴾: ﴿ثم بدلنا﴾؟","answer":"﴿ثم﴾ للتراخي الرتبي أو الزمني؛ فقد أمهلهم بعد الشدة ثم نقلهم إلى الرخاء اختبارًا آخر، والتحول أدعى للاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص74–83.","url":""}]},{"id":"s7-507","number":507,"surah":7,"verses":[95],"verseLabel":"الأعراف: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿بدلنا مكان السيئة الحسنة﴾، دون أن يقال: بدلنا السيئة بالحسنة؟","answer":"جعل الحسنة في مكان السيئة يصور إحلال الرخاء محل الشدة إحلالًا تامًا، كأن موضع البلاء نفسه شُغل بالنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص74–83.","url":""}]},{"id":"s7-508","number":508,"surah":7,"verses":[95],"verseLabel":"الأعراف: 95","question":"لماذا سمّى الشدة ﴿السيئة﴾ والرخاء ﴿الحسنة﴾؟","answer":"سميت الشدة سيئة لأنها تسوءهم، والرخاء حسنة لأنه يحسن عندهم ويسرهم؛ فالتسمية بالنظر إلى أثرهما في الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص74–83.","url":""}]},{"id":"s7-509","number":509,"surah":7,"verses":[95],"verseLabel":"الأعراف: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى عفوا﴾، وما دلالة «عفوا» هنا؟","answer":"﴿عفوا﴾ أي كثروا في العدد والمال ونموا، ومن أصل العفو الزيادة؛ فالرخاء امتد حتى ظهرت آثاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص74–83.","url":""}]},{"id":"s7-510","number":510,"surah":7,"verses":[95],"verseLabel":"الأعراف: 95","question":"لماذا جعل كثرتهم ورخاءهم غاية للتبديل بـ﴿حتى﴾؟","answer":"جعل الكثرة غاية لأن الاختبار بالرخاء بلغ مداه عندها؛ وكان المنتظر أن يشكروا، لكنهم غفلوا ونسبوا الأمر إلى العادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص74–83.","url":""}]},{"id":"s7-511","number":511,"surah":7,"verses":[95],"verseLabel":"الأعراف: 95","question":"ما سرّ تعبيرهم بقولهم: ﴿قد مس آباءنا الضراء والسراء﴾، واختيارهم لفظ ﴿مس﴾؟","answer":"اختير ﴿مس﴾ لما فيه من إصابة خفيفة عابرة؛ فهم هوّنوا الشدة والرخاء وعدوهما مجرد أحوال تمس الأجيال بلا قصد ولا عبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص74–83.","url":""}]},{"id":"s7-512","number":512,"surah":7,"verses":[95],"verseLabel":"الأعراف: 95","question":"لماذا قدّموا ﴿الضراء﴾ على ﴿السراء﴾؟","answer":"قدموا الضراء لأنها الأقرب إلى دفع ما أصابهم أولًا من البأساء والضراء، ثم أتبعوها السراء التي جاءت بعد التبديل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص74–83.","url":""}]},{"id":"s7-513","number":513,"surah":7,"verses":[95],"verseLabel":"الأعراف: 95","question":"لماذا نسبوا تداول الشدة والرخاء إلى عادة الآباء؟","answer":"نسبوها إلى عادة الآباء لينفوا أن تكون إنذارًا من الله، ويجعلوا تداولها قانونًا أعمى لا يستدعي توبة أو شكرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص74–83.","url":""}]},{"id":"s7-514","number":514,"surah":7,"verses":[95],"verseLabel":"الأعراف: 95","question":"لماذا عُطف ﴿فأخذناهم﴾ بالفاء بعد ﴿عفوا وقالوا﴾؟","answer":"الفاء تفيد أن الأخذ جاء عقب اكتمال الغفلة والقول الباطل؛ فلما لم ينتفعوا بالشدة ولا الرخاء جاء الجزاء سريعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص74–83.","url":""}]},{"id":"s7-515","number":515,"surah":7,"verses":[95],"verseLabel":"الأعراف: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿بغتة وهم لا يشعرون﴾، فجمع بين المفاجأة ونفي الشعور؟","answer":"﴿بغتة﴾ تثبت وقوع الأخذ فجأة، و﴿وهم لا يشعرون﴾ تصف حالهم المستمرة من الغفلة وعدم توقع العذاب؛ فجمع الحدث وحال أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص74–83.","url":""}]},{"id":"s7-516","number":516,"surah":7,"verses":[95],"verseLabel":"الأعراف: 95","question":"ما الفرق بين خاتمة ﴿لا يشعرون﴾ هنا و﴿وهم نائمون﴾ و﴿وهم يلعبون﴾ بعدها؟","answer":"﴿لا يشعرون﴾ أعم في نفي إدراك مقدمات العذاب، و﴿نائمون﴾ يصور غفلة الليل وعجزه، و﴿يلعبون﴾ يصور غفلة النهار مع الانشغال باللهو.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص74–83.","url":""}]},{"id":"s7-517","number":517,"surah":7,"verses":[96],"verseLabel":"الأعراف: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو أن أهل القرى﴾ بعد ذكر قرية بالإفراد؟","answer":"انتقل من سنة قرية واحدة إلى جميع القرى؛ ليقرر أن ما سبق أمثلة لقاعدة عامة لا حادثة محصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص84–93.","url":""}]},{"id":"s7-518","number":518,"surah":7,"verses":[96],"verseLabel":"الأعراف: 96","question":"لماذا اقترنت ﴿لو﴾ بـ﴿أن﴾: ﴿ولو أن أهل القرى آمنوا﴾؟","answer":"اقتران ﴿لو﴾ بـ﴿أن﴾ يجعل مضمون الجملة الاسمية المؤولة شرطًا كاملًا: لو تحقق إيمان أهل القرى وتقواهم لتحققت البركات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص84–93.","url":""}]},{"id":"s7-519","number":519,"surah":7,"verses":[96],"verseLabel":"الأعراف: 96","question":"لماذا أضيف ﴿أهل﴾ إلى ﴿القرى﴾ بدل أن يقال: ولو أن القرى آمنت؟","answer":"أسند الإيمان إلى الأهل لأن التكليف والوعد والجزاء يتعلق بالعقلاء الساكنين، لا بالأبنية والأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص84–93.","url":""}]},{"id":"s7-520","number":520,"surah":7,"verses":[96],"verseLabel":"الأعراف: 96","question":"لماذا جمع بين الإيمان والتقوى؟","answer":"الإيمان تصديق القلب وأصل الاستجابة، والتقوى امتثال عملي وترك للمعصية؛ فلا تتم أسباب البركة بأحدهما دون الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص84–93.","url":""}]},{"id":"s7-521","number":521,"surah":7,"verses":[96],"verseLabel":"الأعراف: 96","question":"لماذا عُطف ﴿واتقوا﴾ على ﴿آمنوا﴾ بالواو؟","answer":"الواو تجمع الشرطين من غير جعل أحدهما بدل الآخر؛ فالمطلوب اجتماع الإيمان والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص84–93.","url":""}]},{"id":"s7-522","number":522,"surah":7,"verses":[96],"verseLabel":"الأعراف: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿لفتحنا عليهم بركات﴾، فاستعار الفتح للبركات؟","answer":"صُورت البركات كخزائن مغلقة يفتحها الله فتفيض؛ وفي الفتح معنى السعة بعد المنع وتتابع الخيرات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص84–93.","url":""}]},{"id":"s7-523","number":523,"surah":7,"verses":[96],"verseLabel":"الأعراف: 96","question":"لماذا عُدّي الفتح بـ﴿على﴾: ﴿لفتحنا عليهم﴾؟","answer":"﴿على﴾ تصور البركات نازلةً عليهم من فوق ومحيطةً بهم، وفيها إيحاء بالفيض والشمول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص84–93.","url":""}]},{"id":"s7-524","number":524,"surah":7,"verses":[96],"verseLabel":"الأعراف: 96","question":"لماذا جمع ﴿بركات﴾ ونكّرها؟","answer":"جُمعت لتعدد أنواعها في الدين والدنيا، ونُكرت للتعظيم والتكثير: بركات كثيرة واسعة لا يحيط بها العد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص84–93.","url":""}]},{"id":"s7-525","number":525,"surah":7,"verses":[96],"verseLabel":"الأعراف: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿من السماء والأرض﴾ فجمع جهتي العلو والسفل؟","answer":"جمع السماء والأرض لاستيعاب جهات الرزق: المطر والوحي من العلو، والنبات والثمر والمعادن من الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص84–93.","url":""}]},{"id":"s7-526","number":526,"surah":7,"verses":[96],"verseLabel":"الأعراف: 96","question":"لماذا استدرك بـ﴿ولكن كذبوا﴾، وحذف متعلق التكذيب؟","answer":"الاستدراك يقابل الحال الممكنة بالحال الواقعة: كان طريق البركة مفتوحًا لكنهم كذبوا. وحذف المتعلق ليعم تكذيبهم الرسل والآيات والحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص84–93.","url":""}]},{"id":"s7-527","number":527,"surah":7,"verses":[96],"verseLabel":"الأعراف: 96","question":"لماذا قابل ﴿لفتحنا عليهم﴾ بـ﴿فأخذناهم﴾؟","answer":"قابل الفتح بالأخذ: الإيمان يطلق أبواب الخير، والتكذيب يجعلهم في قبضة العقاب؛ فالصورتان متضادتان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص84–93.","url":""}]},{"id":"s7-528","number":528,"surah":7,"verses":[96],"verseLabel":"الأعراف: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿بما كانوا يكسبون﴾ لا «بما كسبوا»؟","answer":"﴿كانوا يكسبون﴾ يدل على تكرر الذنوب واستمرار اتخاذها كسبًا وعادة، لا على فعل ماض منفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص84–93.","url":""}]},{"id":"s7-529","number":529,"surah":7,"verses":[97,98],"verseLabel":"الأعراف: 97–98","question":"لماذا تكرر الاستفهام: ﴿أفأمن أهل القرى﴾ ثم ﴿أوأمن أهل القرى﴾؟","answer":"كرر الاستفهام ليحيط بزمني الغفلة: الليل والنهار؛ فلا يأمن أهل القرى بأس الله في أي حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص94–105.","url":""}]},{"id":"s7-530","number":530,"surah":7,"verses":[97],"verseLabel":"الأعراف: 97","question":"لماذا دخلت الفاء بين همزة الاستفهام و﴿أمن﴾: ﴿أفأمن﴾؟","answer":"الفاء تعطف الإنكار على ما سبق من أخذ المكذبين؛ أفبعد هذه السنن والوقائع أمن اللاحقون؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص94–99.","url":""}]},{"id":"s7-531","number":531,"surah":7,"verses":[97],"verseLabel":"الأعراف: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يأتيهم بأسنا﴾ فجعل البأس آتيًا؟","answer":"صُور البأس كقادم يتحرك نحوهم، فيفاجئهم من حيث لا يملكون دفعه، وفي ذلك تشخيص للوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص94–99.","url":""}]},{"id":"s7-532","number":532,"surah":7,"verses":[97],"verseLabel":"الأعراف: 97","question":"لماذا اختير ﴿بياتًا﴾ لا «ليلًا»؟","answer":"البيات هو مباغتة العدو ليلًا، فلا يدل على الزمن فقط بل على القصد والمفاجأة وشدة الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص94–99.","url":""}]},{"id":"s7-533","number":533,"surah":7,"verses":[97],"verseLabel":"الأعراف: 97","question":"لماذا خُتمت بـ﴿وهم نائمون﴾ مع أن «بياتًا» يدل على الليل؟","answer":"ذكر النوم بعد البيات لتصوير تمام الغفلة والعجز عند مجيء العذاب، لا لمجرد تحديد الليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص94–99.","url":""}]},{"id":"s7-534","number":534,"surah":7,"verses":[98],"verseLabel":"الأعراف: 98","question":"لماذا عطف الاحتمال الثاني بـ﴿أو﴾: ﴿أوأمن أهل القرى﴾؟","answer":"﴿أو﴾ تقسم وجهي الأمن الموهوم: أأمنوا مجيئه ليلًا، أم أمنوا مجيئه نهارًا؟ وكلاهما منكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص100–105.","url":""}]},{"id":"s7-535","number":535,"surah":7,"verses":[98],"verseLabel":"الأعراف: 98","question":"لماذا كرر ﴿أهل القرى﴾ ولم يضمرهم؟","answer":"أظهر ﴿أهل القرى﴾ لتجديد التهديد وتثبيت الحكم عليهم، ولئلا يضعف التصوير بضمير بعد فصل الآيتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص100–105.","url":""}]},{"id":"s7-536","number":536,"surah":7,"verses":[98],"verseLabel":"الأعراف: 98","question":"لماذا قابل ﴿بياتًا﴾ بـ﴿ضحى﴾ لا بـ«نهارًا»؟","answer":"الضحى وقت ارتفاع النهار وانتشار الحركة والاطمئنان، فقابل البيات لا بمجرد النهار بل بوقت الغفلة في النشاط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص100–105.","url":""}]},{"id":"s7-537","number":537,"surah":7,"verses":[98],"verseLabel":"الأعراف: 98","question":"لماذا خُتمت بـ﴿وهم يلعبون﴾ لا «وهم مستيقظون»؟","answer":"﴿يلعبون﴾ يذم حالهم؛ فهم مستيقظون قادرون على الاعتبار لكنهم مشتغلون بما لا ينفع، وهذا أشد من مجرد اليقظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص100–105.","url":""}]},{"id":"s7-538","number":538,"surah":7,"verses":[98],"verseLabel":"الأعراف: 98","question":"ما سر المقابلة بين ﴿وهم نائمون﴾ و﴿وهم يلعبون﴾؟","answer":"المقابلة تستوعب غفلتين: غفلة اضطرارية بالنوم ليلًا، وغفلة اختيارية باللهو نهارًا؛ فلا زمان يمنع بأس الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص94–105.","url":""}]},{"id":"s7-539","number":539,"surah":7,"verses":[99],"verseLabel":"الأعراف: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿أفأمنوا مكر الله﴾ بعد تكرار ﴿أفأمن أهل القرى﴾؟","answer":"بعد إنكار أمنهم مجيء البأس في الليل والنهار جمع ذلك كله في إنكار أصل الأمن من تدبير الله الخفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص106–111.","url":""}]},{"id":"s7-540","number":540,"surah":7,"verses":[99],"verseLabel":"الأعراف: 99","question":"لماذا سُمّي أخذ الله لهم ﴿مكر الله﴾؟","answer":"سمي أخذهم مكرًا من باب المشاكلة أو باعتبار مجيء العقوبة من حيث لا يشعرون بعد الإمهال؛ وهو عدل وجزاء لا ظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص106–111.","url":""}]},{"id":"s7-541","number":541,"surah":7,"verses":[99],"verseLabel":"الأعراف: 99","question":"لماذا كرر ﴿مكر الله﴾ ظاهرًا في الجملتين ولم يقل: فلا يأمنه؟","answer":"أظهر ﴿مكر الله﴾ مرة ثانية لتفخيمه وتثبيت المهابة في النفس، ولئلا يعود الضمير إلى غير المراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص106–111.","url":""}]},{"id":"s7-542","number":542,"surah":7,"verses":[99],"verseLabel":"الأعراف: 99","question":"لماذا عبّر بالفعل أولًا ﴿أفأمنوا﴾ ثم بالمضارع ﴿فلا يأمن﴾؟","answer":"الماضي ﴿أفأمنوا﴾ ينكر وقوع الأمن منهم، والمضارع ﴿لا يأمن﴾ يقرر قاعدة مستمرة لكل زمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص106–111.","url":""}]},{"id":"s7-543","number":543,"surah":7,"verses":[99],"verseLabel":"الأعراف: 99","question":"لماذا جاءت الفاء في ﴿فلا يأمن مكر الله﴾؟","answer":"الفاء تفريع للقاعدة على الإنكار السابق: لما كان أمنهم باطلًا ثبت أن من يأمن هذا الأمن من الخاسرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص106–111.","url":""}]},{"id":"s7-544","number":544,"surah":7,"verses":[99],"verseLabel":"الأعراف: 99","question":"لماذا قصر الأمن من مكر الله على ﴿القوم الخاسرون﴾؟","answer":"حصر الأمن في الخاسرين لأنه يفضي إلى ترك الحذر والتوبة حتى يفجأ العذاب؛ فلا يصدر إلا عمن خسر بصيرته وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص106–111.","url":""}]},{"id":"s7-545","number":545,"surah":7,"verses":[100],"verseLabel":"الأعراف: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿أولم يهد﴾، وأسند البيان إلى فعل «يهد» بلا فاعل ظاهر؟","answer":"فاعل ﴿يهد﴾ مضمر دل عليه السياق، أي: أوَلم يبيّن لهم ما جرى للأمم؛ والحذف يوجه العناية إلى وضوح الدلالة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص112–122.","url":""}]},{"id":"s7-546","number":546,"surah":7,"verses":[100],"verseLabel":"الأعراف: 100","question":"لماذا وصف اللاحقين بأنهم ﴿يرثون الأرض﴾؟","answer":"وصفهم بالوراثة لأنهم سكنوا أرض من هلك قبلهم وانتقلت إليهم من غيرهم، فكان في ذلك نعمة وعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص112–122.","url":""}]},{"id":"s7-547","number":547,"surah":7,"verses":[100],"verseLabel":"الأعراف: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿الأرض من بعد أهلها﴾، دون أن يقال: ديارهم من بعدهم؟","answer":"﴿الأرض﴾ أوسع من الديار فتشمل السلطان والموارد ومواطن العيش، و﴿أهلها﴾ تستحضر أن أممًا كانت تعمرها ثم زالت.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص112–122.","url":""}]},{"id":"s7-548","number":548,"surah":7,"verses":[100],"verseLabel":"الأعراف: 100","question":"لماذا جاء التركيب ﴿أن لو نشاء﴾؟","answer":"﴿أن﴾ مفسرة لما يهدي إليه الاعتبار، و﴿لو﴾ شرطية تبين أن إصابتهم داخلة تحت مشيئة الله: أن لو نشاء أصبناهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص112–122.","url":""}]},{"id":"s7-549","number":549,"surah":7,"verses":[100],"verseLabel":"الأعراف: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿أصبناهم بذنوبهم﴾ لا «عذبناهم»؟","answer":"الإصابة تصور العقوبة واقعة عليهم وقوع السهم في هدفه، وتربط الجزاء بذنوبهم مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص112–122.","url":""}]},{"id":"s7-550","number":550,"surah":7,"verses":[100],"verseLabel":"الأعراف: 100","question":"ما دلالة الباء في ﴿بذنوبهم﴾؟","answer":"الباء سببية: أصبناهم بسبب ذنوبهم؛ فلا يقع الأخذ اعتباطًا ولا ظلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص112–122.","url":""}]},{"id":"s7-551","number":551,"surah":7,"verses":[100],"verseLabel":"الأعراف: 100","question":"لماذا عدل من الشرط ﴿لو نشاء أصبناهم﴾ إلى المضارع ﴿ونطبع﴾؟","answer":"انتقل إلى المضارع لاستحضار سنة متجددة تصيب المعرضين؛ فالإصابة بالمشيئة، والطبع أثر مستمر يتكرر بإصرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص112–122.","url":""}]},{"id":"s7-552","number":552,"surah":7,"verses":[100],"verseLabel":"الأعراف: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿نطبع على قلوبهم﴾، فجعل القلوب موضع الختم؟","answer":"الطبع ختم يمنع نفوذ الحق، وجعل محله القلوب لأنها موضع الإدراك والقبول؛ فإذا ختمت تعذر انتفاع سائر الحواس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص112–122.","url":""}]},{"id":"s7-553","number":553,"surah":7,"verses":[100],"verseLabel":"الأعراف: 100","question":"لماذا فرّع على طبع القلوب قوله: ﴿فهم لا يسمعون﴾؟","answer":"الفاء تجعل عدم سماع الحق نتيجة للطبع؛ فالمختوم على قلبه يسمع الصوت لكنه لا يسمع سماع قبول وانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص112–122.","url":""}]},{"id":"s7-554","number":554,"surah":7,"verses":[100],"verseLabel":"الأعراف: 100","question":"لماذا نفى السماع لا الفهم أو الإيمان؟","answer":"نُفي السماع لأنه أول منافذ تلقي رسالة النبي المذكورة في السياق؛ فإذا امتنع سماع القبول امتنع الفهم والإيمان من باب أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص112–122.","url":""}]},{"id":"s7-555","number":555,"surah":7,"verses":[3],"verseLabel":"الأعراف: 100؛ التوبة: 87؛ المنافقون: 3","question":"ما سرّ اختلاف الخاتمة بعد الطبع على القلوب: ﴿فهم لا يسمعون﴾ في الأعراف، و﴿فهم لا يفقهون﴾ في التوبة والمنافقون؟","answer":"ختم الأعراف بـ﴿لا يسمعون﴾ لأن السياق في توالي الرسل والإنذار الذي يتلقى بالسماع، وختم التوبة والمنافقون بـ﴿لا يفقهون﴾ لأن المقام في سوء إدراك أحوال النفاق وأحكامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص19، مادة التوبة: 87.","url":""}]},{"id":"s7-556","number":556,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿تلك القرى﴾ باسم الإشارة للبعيد؟","answer":"الإشارة للبعد تعظم شأن القرى المذكورة وتصورها وقد بعدت في الزمن وصارت آثارًا للعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص123–136.","url":""}]},{"id":"s7-557","number":557,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿تلك القرى﴾ لا «تلك أخبار القرى»؟","answer":"حذف المضاف وجعل القرى نفسها مقصوصة مبالغةً في إحضارها؛ فكأنها قائمة بمشاهدها لا مجرد أخبار تروى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص123–136.","url":""}]},{"id":"s7-558","number":558,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"لماذا عبّر بالمضارع ﴿نقص عليك﴾ عن قصص وقع في الماضي؟","answer":"المضارع يستحضر القصص ويجدد عرضه أمام السامع، فكأن الوقائع الماضية تحدث الآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص123–136.","url":""}]},{"id":"s7-559","number":559,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"لماذا عُدّي القص بـ﴿على﴾: ﴿نقص عليك﴾؟","answer":"عُدّي القص بـ﴿على﴾ لأنه إلقاء خبر متتابع على المخاطب وعرضه عليه جزءًا بعد جزء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص123–136.","url":""}]},{"id":"s7-560","number":560,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿من أنبائها﴾ بزيادة ﴿من﴾؟","answer":"﴿من﴾ للتبعيض؛ فما قصه القرآن من أنبائها هو القدر المختار للعبرة، لا جميع تفاصيل تاريخها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص123–136.","url":""}]},{"id":"s7-561","number":561,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد جاءتهم رسلهم﴾ مع أن الجملة تفسر أنباء القرى؟","answer":"الجملة تبين أهم أنبائها وتؤكد باللام وقد أن الرسل بلغوهم فعلًا، فلا عذر لهم في التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص123–136.","url":""}]},{"id":"s7-562","number":562,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"لماذا أضاف الرسل إليهم: ﴿رسلهم﴾؟","answer":"الإضافة إلى ضميرهم تفيد أن كل قوم جاءهم رسولهم المختص بهم، العارف بلسانهم وحالهم والقائم بالحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص123–136.","url":""}]},{"id":"s7-563","number":563,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"لماذا جمع ﴿البينات﴾؟","answer":"جُمعت لتعدد الحجج والمعجزات والدلائل التي جاء بها الرسل، فلم يكن التكذيب بعد بينة واحدة خفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص123–136.","url":""}]},{"id":"s7-564","number":564,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿فما كانوا ليؤمنوا﴾ بدل «فلم يؤمنوا»؟","answer":"اللام في ﴿ليؤمنوا﴾ لام الجحود بعد ﴿ما كان﴾؛ فالتعبير ينفي صلاحية الإيمان ووقوعه منهم بعد رسوخ التكذيب، وهو أبلغ من مجرد ﴿لم يؤمنوا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص123–136.","url":""}]},{"id":"s7-565","number":565,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿بما كذبوا من قبل﴾، وما المراد بـ«من قبل»؟","answer":"أي لم يكونوا ليصدقوا عند مجيء الرسل بما سبق أن كذبوا به حين أخذ عليهم الميثاق أو عند أول مجيء البينات؛ فالتكذيب السابق أورث الإصرار اللاحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص123–136.","url":""}]},{"id":"s7-566","number":566,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"لماذا خُتمت بـ﴿كذلك يطبع الله على قلوب الكافرين﴾ بعد قوله قبلها: ﴿ونطبع على قلوبهم﴾؟","answer":"الخاتمة تحول أخبار القرى إلى سنة عامة: مثل ذلك الطبع الناشئ عن الإصرار يطبع الله على قلوب كل كافر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص123–136.","url":""}]},{"id":"s7-567","number":567,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"لماذا أظهر اسم الله في ﴿يطبع الله﴾ بعد ضمير التعظيم ﴿نطبع﴾؟","answer":"أظهر اسم الله لتفخيم الفاعل وتقرير أن الطبع حكم إلهي عادل، وليناسب التصريح السابق بـ﴿مكر الله﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص123–136.","url":""}]},{"id":"s7-568","number":568,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الأعراف: ﴿كذلك يطبع الله﴾ بالاسم الظاهر، وقوله تعالى في يونس في القصة النظيرة: ﴿كذلك نطبع﴾ بنون العظمة؟","answer":"ناسب التصريح باسم الله في الأعراف ما تقدمه من قوله ﴿أفأمنوا مكر الله﴾، وناسبت نون العظمة في يونس ما تقدم من ﴿فنجيناه﴾ و﴿بعثنا﴾ و﴿جعلناهم﴾.","sources":[{"label":"كشف المعاني في المتشابه من المثاني: قوله تعالى كذلك يطبع الله.","url":""}]},{"id":"s7-569","number":569,"surah":7,"verses":[101],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿بما كذبوا من قبل﴾، وفي يونس: ﴿بما كذبوا به﴾؟","answer":"وافق ختام الأعراف مطلع المقطع ﴿ولكن كذبوا﴾ بلا باء، فذكر التكذيب السابق على الأسلوب نفسه؛ وفي يونس سبق ﴿فكذبوه﴾ و﴿كذبوا بآياتنا﴾ فجيء بـ﴿بما كذبوا به﴾.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-570","number":570,"surah":7,"verses":[102],"verseLabel":"الأعراف: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿وما وجدنا لأكثرهم من عهد﴾، دون أن يقال: وما وفى أكثرهم؟","answer":"عبّر بالوجدان ليصور البحث والاختبار ثم عدم العثور على عهد لهم؛ و﴿من﴾ تنفي وجود أدنى وفاء، لا مجرد وقوع إخلال واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص137–146.","url":""}]},{"id":"s7-571","number":571,"surah":7,"verses":[102],"verseLabel":"الأعراف: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿لأكثرهم﴾ ولم يعمم الحكم على الجميع؟","answer":"قال ﴿لأكثرهم﴾ إنصافًا؛ إذ بقي من وفى بالعهد وآمن، فلا يعمم الذم على الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص137–146.","url":""}]},{"id":"s7-572","number":572,"surah":7,"verses":[102],"verseLabel":"الأعراف: 102","question":"لماذا زيدت ﴿من﴾ في ﴿من عهد﴾؟","answer":"﴿من﴾ زائدة في سياق النفي لتوكيده واستغراق جنس العهد: لم يوجد لأكثرهم شيء من الوفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص137–146.","url":""}]},{"id":"s7-573","number":573,"surah":7,"verses":[102],"verseLabel":"الأعراف: 102","question":"ما المراد بـ﴿عهد﴾ هنا: الوصية الفطرية أم الوفاء بما عاهدوا عليه؟","answer":"يشمل عهد الفطرة والتوحيد وما أخذه الله عليهم، كما يشمل وفاءهم بما عاهدوا الرسل عليه؛ والجامع نقض الالتزام بالحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص137–146.","url":""}]},{"id":"s7-574","number":574,"surah":7,"verses":[102],"verseLabel":"الأعراف: 102","question":"لماذا قابل النفي بـ﴿وإن وجدنا أكثرهم لفاسقين﴾؟","answer":"قابل عدم وجدان العهد بإثبات الفسق ليبين أن السبب خروجهم المتكرر عن الطاعة، لا خفاء الحق عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص137–146.","url":""}]},{"id":"s7-575","number":575,"surah":7,"verses":[102],"verseLabel":"الأعراف: 102","question":"لماذا اختلف معنى ﴿وجدنا﴾ في الموضعين المتجاورين؟","answer":"الأول ﴿وجدنا لأكثرهم﴾ بمعنى ألفينا لهم عهدًا، والثاني ﴿وجدنا أكثرهم﴾ بمعنى حكمنا عليهم وعلمنا حالهم بالمشاهدة والاختبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص137–146.","url":""}]},{"id":"s7-576","number":576,"surah":7,"verses":[102],"verseLabel":"الأعراف: 102","question":"لماذا أكد الخبر بـ﴿إن﴾ واللام: ﴿وإن وجدنا أكثرهم لفاسقين﴾؟","answer":"أكد بـ﴿إن﴾ واللام لأن فسق الأكثر حقيقة ثابتة كشفتها قصص القرى، ولدفع توهم أن نقضهم كان عارضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص137–146.","url":""}]},{"id":"s7-577","number":577,"surah":7,"verses":[102],"verseLabel":"الأعراف: 102","question":"لماذا اختيرت خاتمة ﴿لفاسقين﴾ بعد الحديث عن العهد؟","answer":"الفسق خروج عن الطاعة والعهد؛ فناسب ختام الآية التي نفت الوفاء وأثبتت النقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص137–146.","url":""}]},{"id":"s7-578","number":578,"surah":7,"verses":[103],"verseLabel":"الأعراف: 103","question":"لماذا بدأت قصة موسى بـ﴿ثم بعثنا﴾ مع أن بعث الرسل متعاقب؟","answer":"﴿ثم﴾ للتراخي الرتبي والزمني؛ فقصة موسى أطول وأعظم تفصيلًا في السورة، وجاءت بعد جماعة الرسل والأمم السابقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص147–155.","url":""}]},{"id":"s7-579","number":579,"surah":7,"verses":[103],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعدهم﴾، وإلى من يعود الضمير؟","answer":"يعود إلى الرسل المذكورين أو إلى الأمم والقرى المتقدمة؛ أي بعد أولئك السابقين بعث الله موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص147–155.","url":""}]},{"id":"s7-580","number":580,"surah":7,"verses":[103],"verseLabel":"الأعراف: 103","question":"لماذا قدّم ﴿من بعدهم﴾ على ﴿موسى﴾؟","answer":"قُدم الظرف لربط قصة موسى بسلسلة القصص السابقة وإبراز تعاقب الرسالات قبل تسمية الرسول الجديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص147–155.","url":""}]},{"id":"s7-581","number":581,"surah":7,"verses":[103],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿بعثنا... موسى﴾، دون أن يقال: أرسلنا موسى؟","answer":"البعث يتضمن الإنهاض والإثارة لمهمة عظيمة، فناسب إخراج موسى لمواجهة سلطان فرعون بآيات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص147–155.","url":""}]},{"id":"s7-582","number":582,"surah":7,"verses":[103],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿بآياتنا﴾ قبل ذكر الجهة المبعوث إليها؟","answer":"تقديم ﴿بآياتنا﴾ يبرز عدة موسى وحجته قبل ذكر الخصم؛ فهو مبعوث مؤيد بالآيات لا داخل المواجهة بقوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص147–155.","url":""}]},{"id":"s7-583","number":583,"surah":7,"verses":[103],"verseLabel":"الأعراف: 103","question":"ما دلالة الباء في ﴿بآياتنا﴾؟","answer":"الباء للمصاحبة والملابسة، أي بعثناه مصحوبًا بآياتنا، وقيل للاستعانة والتأييد بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص147–155.","url":""}]},{"id":"s7-584","number":584,"surah":7,"verses":[103],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى فرعون وملئه﴾ لا «إلى فرعون وقومه»؟","answer":"خُص فرعون وملؤه لأنهم مركز السلطة والتدبير وقادة التكذيب، ومن ورائهم يتبع عامة القوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص147–155.","url":""}]},{"id":"s7-585","number":585,"surah":7,"verses":[103],"verseLabel":"الأعراف: 103","question":"ما سرّ تقديم فرعون على ملئه؟","answer":"قدم فرعون لأنه رأس الطغيان وصاحب الأمر، وملؤه تابعون لسلطانه ومؤيدون له.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص147–155.","url":""}]},{"id":"s7-586","number":586,"surah":7,"verses":[103],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فظلموا بها﴾، فعُدّي الظلم بالباء؟","answer":"الباء متعلقة بالتكذيب أو بمعنى الجحود؛ أي ظلموا بسبب الآيات أو كفروا بها ووضعوها موضع الإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص147–155.","url":""}]},{"id":"s7-587","number":587,"surah":7,"verses":[103],"verseLabel":"الأعراف: 103","question":"لماذا حُذف مفعول ﴿ظلموا﴾؟","answer":"حذف المفعول ليعم ظلمهم أنفسهم وموسى وقومه والحق، فلا يحصر فسادهم في جهة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص147–155.","url":""}]},{"id":"s7-588","number":588,"surah":7,"verses":[103],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فانظر﴾ بالفاء مباشرة بعد ظلمهم؟","answer":"الفاء تفرع الأمر بالنظر على ظلمهم مباشرة؛ فمن تأمل سببهم رأى عاقبته متصلة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص147–155.","url":""}]},{"id":"s7-589","number":589,"surah":7,"verses":[103],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿كيف كان عاقبة المفسدين﴾ لا «ما عاقبتهم»؟","answer":"الاستفهام بـ﴿كيف﴾ يلفت إلى هيئة العاقبة وفظاعتها لا إلى مجرد حصولها، فيستدعي نظرًا واعتبارًا أعمق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص147–155.","url":""}]},{"id":"s7-590","number":590,"surah":7,"verses":[103],"verseLabel":"الأعراف: 103","question":"لماذا سمّاهم ﴿المفسدين﴾ بعد وصف فعلهم بالظلم؟","answer":"سماهم مفسدين لأن ظلمهم بالآيات لم يقف عند أنفسهم، بل أفسدوا الناس والبلاد وصدوا عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص147–155.","url":""}]},{"id":"s7-591","number":591,"surah":7,"verses":[104],"verseLabel":"الأعراف: 104","question":"ما سرّ نداء موسى فرعون باسمه السلطاني: ﴿يا فرعون﴾؟","answer":"ناداه بلقبه المعروف الذي به سلطانه على قومه، مواجهةً له في مركز دعواه من غير تزلف ولا خوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص156–161.","url":""}]},{"id":"s7-592","number":592,"surah":7,"verses":[104],"verseLabel":"الأعراف: 104","question":"ما سرّ ترك لقب «ملك مصر» في خطاب موسى لفرعون؟","answer":"ترك لقب الملك لأن ملكه محدود مدعى، وخاطبه بالاسم الذي اشتهر به دون إقرار له بربوبية أو ملك مطلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص156–161.","url":""}]},{"id":"s7-593","number":593,"surah":7,"verses":[104],"verseLabel":"الأعراف: 104","question":"لماذا بدأ موسى كلامه بالتوكيد: ﴿إني رسول﴾؟","answer":"أكد بـ﴿إن﴾ لأن فرعون مظنة الإنكار والتكذيب، ولإعلان حقيقة الرسالة بثبات أمام سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص156–161.","url":""}]},{"id":"s7-594","number":594,"surah":7,"verses":[104],"verseLabel":"الأعراف: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿رسول من رب العالمين﴾ لا «رسول الله»؟","answer":"﴿من رب العالمين﴾ تهدم دعوى فرعون للربوبية وتبين أن مرسل موسى هو رب الجميع، أما ﴿رسول الله﴾ فلا تظهر هذه المقابلة بالقدر نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص156–161.","url":""}]},{"id":"s7-595","number":595,"surah":7,"verses":[104],"verseLabel":"الأعراف: 104","question":"لماذا نكّر ﴿رسول﴾؟","answer":"نُكر ﴿رسول﴾ لإبراز الوصف وتعظيم شأن الرسالة: إني واحد من جنس رسل الله الصادقين، لا طالب ملك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص156–161.","url":""}]},{"id":"s7-596","number":596,"surah":7,"verses":[104],"verseLabel":"الأعراف: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿من رب العالمين﴾ بـ﴿من﴾؟","answer":"﴿من﴾ لابتداء الغاية؛ فرسالته صادرة من رب العالمين ووحيه من عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص156–161.","url":""}]},{"id":"s7-597","number":597,"surah":7,"verses":[104],"verseLabel":"الأعراف: 104","question":"ما مناسبة وصف الله بـ﴿رب العالمين﴾ في مواجهة فرعون؟","answer":"وصفه برب العالمين في مواجهة فرعون لنفي ربوبيته المزعومة وإثبات أن موسى وفرعون وكل الخلق تحت تدبير رب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص156–161.","url":""}]},{"id":"s7-598","number":598,"surah":7,"verses":[105],"verseLabel":"الأعراف: 105","question":"لماذا بدأ وصف نفسه بـ﴿حقيق على أن لا أقول على الله إلا الحق﴾ قبل إظهار المعجزة؟","answer":"قدم صدقه وأمانته في القول على المعجزة لأن دلالة الآية لا تنفصل عن دعوى حاملها؛ فهو ملتزم ألا ينسب إلى الله إلا الحق ثم يقيم البينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص162–170.","url":""}]},{"id":"s7-599","number":599,"surah":7,"verses":[105],"verseLabel":"الأعراف: 105","question":"لماذا عُدّي ﴿حقيق﴾ بـ﴿على﴾ في قراءة الجمهور؟","answer":"ضُمّن ﴿حقيق﴾ معنى حريص أو ثابت، فعدي بـ﴿على﴾؛ أي واجب ثابت عليّ ألا أقول على الله إلا الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص162–170.","url":""}]},{"id":"s7-600","number":600,"surah":7,"verses":[105],"verseLabel":"الأعراف: 105","question":"ما أثر قراءة ﴿حقيقٌ عليَّ﴾ في معنى الآية؟","answer":"على قراءة ﴿حقيق عليَّ﴾ يكون المعنى: واجب عليّ ولازم لي ألا أقول على الله إلا الحق، فتصرح القراءة بالتزام موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص162–170.","url":""}]},{"id":"s7-601","number":601,"surah":7,"verses":[105],"verseLabel":"الأعراف: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿أن لا أقول على الله﴾ لا «عن الله»؟","answer":"استعمل ﴿على الله﴾ لأن القول المنسوب إليه كأنه محمول عليه؛ وفيه تشديد النهي عن اختلاق شيء وإضافته إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص162–170.","url":""}]},{"id":"s7-602","number":602,"surah":7,"verses":[105],"verseLabel":"الأعراف: 105","question":"لماذا جاء القصر بـ﴿إلا الحق﴾؟","answer":"القصر يحصر كل ما يقوله موسى منسوبًا إلى الله في الحق وحده، فينفي عنه أدنى افتراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص162–170.","url":""}]},{"id":"s7-603","number":603,"surah":7,"verses":[105],"verseLabel":"الأعراف: 105","question":"لماذا عرّف ﴿الحق﴾؟","answer":"عُرّف ﴿الحق﴾ للدلالة على الحق المعروف الكامل الذي لا يلابسه باطل، لا على قول صادق جزئي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص162–170.","url":""}]},{"id":"s7-604","number":604,"surah":7,"verses":[105],"verseLabel":"الأعراف: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿قد جئتكم ببينة﴾، دون أن يقال: معي بينة؟","answer":"﴿جئتكم﴾ تصور إحضار الحجة إليهم وبذلها بين أيديهم، أما «معي بينة» فقد تدل على مجرد المصاحبة دون إظهارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص162–170.","url":""}]},{"id":"s7-605","number":605,"surah":7,"verses":[105],"verseLabel":"الأعراف: 105","question":"لماذا أفرد ﴿ببينة﴾ مع تعدد آيات موسى؟","answer":"أفرد البينة باعتبار جنس الحجة أو المعجزة الجامعة الدالة على الرسالة، وإن تعددت أفراد الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص162–170.","url":""}]},{"id":"s7-606","number":606,"surah":7,"verses":[105],"verseLabel":"الأعراف: 105","question":"لماذا كرر وصف الله بـ﴿ربكم﴾ بعد قوله ﴿رب العالمين﴾؟","answer":"انتقل من رب العالمين إلى ﴿ربكم﴾ لإلزام المخاطبين خاصة: الرب العام هو ربهم الذي تجب طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص162–170.","url":""}]},{"id":"s7-607","number":607,"surah":7,"verses":[105],"verseLabel":"الأعراف: 105","question":"لماذا انتقل من المفرد في خطاب فرعون إلى الجمع: ﴿جئتكم... ربكم﴾؟","answer":"بدأ بمواجهة فرعون، ثم عم الخطاب فرعون وملأه الحاضرين لأن الحجة والمطالبة متوجهتان إليهم جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص162–170.","url":""}]},{"id":"s7-608","number":608,"surah":7,"verses":[105],"verseLabel":"الأعراف: 105","question":"لماذا كانت أول مطالبه: ﴿فأرسل معي بني إسرائيل﴾؟","answer":"بدأ بتحرير بني إسرائيل لأن فرعون استعبدهم، ولأن تمكينهم من الخروج مع رسولهم مقتضى الرسالة ورفع الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص162–170.","url":""}]},{"id":"s7-609","number":609,"surah":7,"verses":[105],"verseLabel":"الأعراف: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿معي﴾ لا «إليّ» أو «معنا»؟","answer":"﴿معي﴾ تفيد المصاحبة في الخروج تحت قيادته، لا مجرد إرسالهم إليه؛ وأفرد لأن موسى المتصدر للخطاب والطلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص162–170.","url":""}]},{"id":"s7-610","number":610,"surah":7,"verses":[106],"verseLabel":"الأعراف: 106","question":"لماذا أجاب فرعون بشرط: ﴿إن كنت جئت بآية﴾ مع أن موسى قال: ﴿قد جئتكم ببينة﴾؟","answer":"تجاهل فرعون وصف البينة وردّه إلى شرط مشكوك فيه ﴿إن كنت﴾ مكابرةً، كأنه لم يثبت عنده شيء بعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص171–174.","url":""}]},{"id":"s7-611","number":611,"surah":7,"verses":[106],"verseLabel":"الأعراف: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿بآية﴾ لا ﴿ببينة﴾ كما قال موسى؟","answer":"سماها فرعون ﴿آية﴾ باعتبارها علامة مطلوبة، بينما سماها موسى ﴿بينة﴾ باعتبار وضوح دلالتها وبرهانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص171–174.","url":""}]},{"id":"s7-612","number":612,"surah":7,"verses":[106],"verseLabel":"الأعراف: 106","question":"لماذا أمره بقوله: ﴿فأت بها﴾؟","answer":"الفاء جواب للشرط؛ أي إن كان معك دليل كما تزعم فأحضره وأظهره، وفي الأمر تحدٍّ واستخفاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص171–174.","url":""}]},{"id":"s7-613","number":613,"surah":7,"verses":[106],"verseLabel":"الأعراف: 106","question":"لماذا أعاد الشرط: ﴿إن كنت من الصادقين﴾؟","answer":"أعاد الشرط تشكيكًا في صدقه وتحديًا له، فجعل إظهار الآية محك الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص171–174.","url":""}]},{"id":"s7-614","number":614,"surah":7,"verses":[106],"verseLabel":"الأعراف: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿من الصادقين﴾ لا «صادقًا»؟","answer":"﴿من الصادقين﴾ تدخله في زمرة موصوفة بالصدق إن ثبتت الآية، وهي أبلغ في تثبيت الصفة من «صادقًا» المفردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص171–174.","url":""}]},{"id":"s7-615","number":615,"surah":7,"verses":[107],"verseLabel":"الأعراف: 107","question":"لماذا عطف إلقاء العصا بالفاء: ﴿فألقى عصاه﴾؟","answer":"الفاء تدل على سرعة امتثال موسى للتحدي من غير تردد؛ فما إن طلب الآية حتى ألقى العصا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص175–182.","url":""}]},{"id":"s7-616","number":616,"surah":7,"verses":[107],"verseLabel":"الأعراف: 107","question":"لماذا أضاف العصا إلى موسى: ﴿عصاه﴾؟","answer":"الإضافة تؤكد أنها عصاه المعهودة البسيطة التي يعرفها، فتظهر المفارقة المعجزة حين تنقلب ثعبانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص175–182.","url":""}]},{"id":"s7-617","number":617,"surah":7,"verses":[107],"verseLabel":"الأعراف: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا هي ثعبان﴾ بأداة المفاجأة؟","answer":"﴿إذا﴾ الفجائية تصور التحول المباغت من عصا جامدة إلى ثعبان حاضر، من غير زمن أو معالجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص175–182.","url":""}]},{"id":"s7-618","number":618,"surah":7,"verses":[107],"verseLabel":"الأعراف: 107","question":"لماذا أتى بضمير الفصل أو العماد ﴿هي﴾ بين ﴿إذا﴾ و﴿ثعبان﴾؟","answer":"الضمير يفصل ويثبت هوية المتحول: فإذا العصا نفسها ثعبان، وفيه تقوية للمفاجأة والتعيين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص175–182.","url":""}]}]);
